        ('POSTALCODE', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'CURRENT_PERMANENT_OVERSEAS_ADDRESS_PIN_CODE', 'COALESCE, TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("CURRENT_PERMANENT_OVERSEAS_ADDRESS_PIN_CODE")), '''')'),
        ('POSTALCODE', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'LOCAL_ADDRESS_PIN_CODE', 'COALESCE, TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("LOCAL_ADDRESS_PIN_CODE")), '''')'),
        ('STATENAME', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'CORRESPONDENCE_LOCAL_ADDRESS_STATE', 'COALESCE, TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("CORRESPONDENCE_LOCAL_ADDRESS_STATE")), '''')'),
        ('STATENAME', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'CURRENT_PERMANENT_OVERSEAS_ADDRESS_STATE_UT', 'COALESCE, TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("CURRENT_PERMANENT_OVERSEAS_ADDRESS_STATE_UT")), '''')')
),
raw_cols as (
    select table_catalog, table_schema, table_name, column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PROD_MIRROR_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'MAXI_RAW'
       and table_name in ('BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS_ADDRESS_PROPERTY_PIVOT_VW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW')
),
sat_cols as (
    select column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'BGIL_DATA_MODEL'
       and table_name = 'SAT_COMMON_ADDRESS'
)
select 'MAXIMUS' as project, 'SAT_COMMON_ADDRESS' as satellite,
       l.sat_column, case when s.data_type = 'TEXT' then 'TEXT(' || s.char_len || ')' when s.data_type = 'NUMBER' then 'NUMBER(' || s.num_prec || ',' || s.num_scale || ')' when s.data_type like 'TIMESTAMP%' then s.data_type || '(' || s.dt_prec || ')' else s.data_type end as sat_type,
       l.raw_table, l.raw_column, case when r.data_type = 'TEXT' then 'TEXT(' || r.char_len || ')' when r.data_type = 'NUMBER' then 'NUMBER(' || r.num_prec || ',' || r.num_scale || ')' when r.data_type like 'TIMESTAMP%' then r.data_type || '(' || r.dt_prec || ')' else r.data_type end as raw_type,
       l.transform_flags,
       case
         when r.data_type is null then 'FAIL - RAW COLUMN NOT FOUND'
         when s.data_type is null then 'FAIL - SAT COLUMN NOT FOUND'
         when r.data_type = 'NUMBER' and r.num_scale > 0 and l.transform_flags like '%SCALE0%'
              then 'FAIL - DECIMALS LOST (cast to integer NUMBER on load)'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER' and s.num_scale < r.num_scale then 'FAIL - DECIMALS LOST'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER'
              and s.num_prec - s.num_scale < r.num_prec - r.num_scale then 'FAIL - PRECISION RISK'
         when r.data_type = 'TEXT' and s.data_type = 'TEXT' and s.char_len < r.char_len then 'FAIL - TRUNCATION RISK (length)'
         when r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%' and s.dt_prec < r.dt_prec
              then 'FAIL - FRACTIONAL SECONDS TRUNCATED'
         when r.data_type = 'DATE' and s.data_type like 'TIMESTAMP%' then 'REVIEW - DATE LOADED AS TIMESTAMP'
         when r.data_type <> 'TEXT' and s.data_type = 'TEXT' then 'REVIEW - STORED AS TEXT (see query b)'
         when r.data_type = 'TEXT' and s.data_type <> 'TEXT' then 'REVIEW - TEXT CONVERTED TO ' || s.data_type
         when r.data_type <> s.data_type and not (r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%')
              then 'REVIEW - TYPE CHANGED'
         when l.transform_flags like '%TRIM%' then 'PASS (whitespace trimmed by design)'
         else 'PASS'
       end as type_verdict,
       l.transform
  from lineage l
  left join raw_cols r
         on r.table_catalog = l.raw_db and r.table_schema = l.raw_schema
        and r.table_name = l.raw_table and r.column_name = l.raw_column
  left join sat_cols s on s.column_name = l.sat_column
 order by l.sat_column, l.raw_table, l.raw_column;

-- SQL query (b) -- value format on the sample (1:1 mapped columns; run the ALTER SESSION first)
alter session set TIMESTAMP_NTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9',
                  TIMESTAMP_LTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  TIMESTAMP_TZ_OUTPUT_FORMAT  = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  DATE_OUTPUT_FORMAT          = 'YYYY-MM-DD';

with sat_rows as (
    -- this project's rows of the satellite
    select s.LOCATION_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'ADDRESSLINE1', to_varchar(s."ADDRESSLINE1"),
               'ADDRESSLINE2', to_varchar(s."ADDRESSLINE2"),
               'ADDRESSLINE3', to_varchar(s."ADDRESSLINE3"),
               'CITY', to_varchar(s."CITY"),
               'COUNTRYNAME', to_varchar(s."COUNTRYNAME"),
               'DISTRICT', to_varchar(s."DISTRICT"),
               'POSTALCODE', to_varchar(s."POSTALCODE"),
               'STATENAME', to_varchar(s."STATENAME"),
               'LANDMARK', to_varchar(s."LANDMARK"),
               'LOCALITY', to_varchar(s."LOCALITY"),
               'POSTOFFICENAME', to_varchar(s."POSTOFFICENAME"),
               'CAREOFNAME', to_varchar(s."CAREOFNAME")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADDRESS s
     where startswith(s.RECORD_SOURCE, 'MAXIMUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
raw_vals as (
    -- 1. BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (case when coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("ADDRESS1")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("ADDRESS2")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("ADDRESS3")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("CITY")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("DISTRICT")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("STATE")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("PINCODE")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("COUNTRY")), ''))))) is null then null else md5(concat_ws('|', coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("ADDRESS1")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("ADDRESS2")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("ADDRESS3")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("CITY")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("DISTRICT")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("STATE")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("PINCODE")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("COUNTRY")), '')))), ''))) end)) AS VARCHAR))), '')) as hkey,
           'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS,
           lateral flatten(input => object_construct_keep_null(
                                     'ADDRESSLINE1', array_construct(to_varchar("ADDRESS1"), typeof(to_variant("ADDRESS1"))),
                                     'ADDRESSLINE2', array_construct(to_varchar("ADDRESS2"), typeof(to_variant("ADDRESS2"))),
                                     'ADDRESSLINE3', array_construct(to_varchar("ADDRESS3"), typeof(to_variant("ADDRESS3"))),
                                     'CITY', array_construct(to_varchar("CITY"), typeof(to_variant("CITY"))),
                                     'COUNTRYNAME', array_construct(to_varchar("COUNTRY"), typeof(to_variant("COUNTRY"))),
                                     'DISTRICT', array_construct(to_varchar("DISTRICT"), typeof(to_variant("DISTRICT"))),
                                     'POSTALCODE', array_construct(to_varchar("PINCODE"), typeof(to_variant("PINCODE"))),
                                     'STATENAME', array_construct(to_varchar("STATE"), typeof(to_variant("STATE")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS_ADDRESS_PROPERTY_PIVOT_VW
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (case when coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("LAND_MARK")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("AREA")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("POST_OFFICE")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("CITY")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("STATE")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("PINCODE")), ''))))) is null then null else md5(concat_ws('|', coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("LAND_MARK")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("AREA")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("POST_OFFICE")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("CITY")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("STATE")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("PINCODE")), '')))), ''))) end)) AS VARCHAR))), '')) as hkey,
           'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS_ADDRESS_PROPERTY_PIVOT_VW' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS_ADDRESS_PROPERTY_PIVOT_VW,
           lateral flatten(input => object_construct_keep_null(
                                     'CITY', array_construct(to_varchar("CITY"), typeof(to_variant("CITY"))),
                                     'LANDMARK', array_construct(to_varchar("LAND_MARK"), typeof(to_variant("LAND_MARK"))),
                                     'LOCALITY', array_construct(to_varchar("AREA"), typeof(to_variant("AREA"))),
                                     'POSTALCODE', array_construct(to_varchar("PINCODE"), typeof(to_variant("PINCODE"))),
                                     'POSTOFFICENAME', array_construct(to_varchar("POST_OFFICE"), typeof(to_variant("POST_OFFICE"))),
                                     'STATENAME', array_construct(to_varchar("STATE"), typeof(to_variant("STATE")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (case when coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("OUR_OFFICE_ADDRESS")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("CURRENT_PERMANENT_OVERSEAS_ADDRESS_LINE_2")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("CURRENT_PERMANENT_OVERSEAS_ADDRESS_LINE_3")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("CURRENT_PERMANENT_OVERSEAS_ADDRESS_CITY_TOWN_VILLAGE")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("CORRESPONDENCE_LOCAL_ADDRESS_DISTRICT")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("CURRENT_PERMANENT_OVERSEAS_ADDRESS_STATE_UT")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("LOCAL_ADDRESS_PIN_CODE")), '')))), upper(trim(to_varchar(nullif(trim(to_varchar("CURRENT_PERMANENT_OVERSEAS_ADDRESS_COUNTRY")), ''))))) is null then null else md5(concat_ws('|', coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("OUR_OFFICE_ADDRESS")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("CURRENT_PERMANENT_OVERSEAS_ADDRESS_LINE_2")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("CURRENT_PERMANENT_OVERSEAS_ADDRESS_LINE_3")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("CURRENT_PERMANENT_OVERSEAS_ADDRESS_CITY_TOWN_VILLAGE")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("CORRESPONDENCE_LOCAL_ADDRESS_DISTRICT")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("CURRENT_PERMANENT_OVERSEAS_ADDRESS_STATE_UT")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("LOCAL_ADDRESS_PIN_CODE")), '')))), ''), coalesce(upper(trim(to_varchar(nullif(trim(to_varchar("CURRENT_PERMANENT_OVERSEAS_ADDRESS_COUNTRY")), '')))), ''))) end)) AS VARCHAR))), '')) as hkey,
           'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW,
           lateral flatten(input => object_construct_keep_null(
                                     'CAREOFNAME', array_construct(to_varchar("ADDRESSEE"), typeof(to_variant("ADDRESSEE"))),
                                     'DISTRICT', array_construct(to_varchar("CORRESPONDENCE_LOCAL_ADDRESS_DISTRICT"), typeof(to_variant("CORRESPONDENCE_LOCAL_ADDRESS_DISTRICT")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
),
classified as (
    select v.hkey, v.rs, v.col,
           case
             when equal_null(v.val, r.raw_value) then 0                                                  -- EXACT
             when v.val is null and nullif(trim(r.raw_value), '') is null then 1                         -- BLANK -> NULL (by design)
             when v.val = trim(r.raw_value) then 1                                                       -- WHITESPACE TRIMMED (by design)
             when r.raw_type <> 'VARCHAR' and v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 2             -- TYPED VALUE KEPT, TEXT FORM DIFFERS
             when r.raw_type <> 'VARCHAR' and try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 2
             when v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 3             -- DATE/TIME RE-FORMATTED
             when try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 3             -- NUMBER RE-FORMATTED
             when try_to_decimal(r.raw_value, 38, 12) <> round(try_to_decimal(r.raw_value, 38, 12), 0)
                  and try_to_decimal(v.val, 38, 12) = round(try_to_decimal(r.raw_value, 38, 12), 0) then 4  -- DECIMALS LOST
             when startswith(r.raw_value, v.val) then 5                                                  -- TRUNCATED
             else 6                                                                            -- DIFFERENT VALUE
           end as cls
      from sat_cols v
      join raw_vals r on r.hkey = v.hkey and r.rs_key = v.rs_key and r.col = v.col
),
best as (
    -- a key can have several RAW rows: keep the closest one per (unit, column)
    select hkey, rs, col, min(cls) as cls from classified group by hkey, rs, col
)
select 'MAXIMUS' as project, 'SAT_COMMON_ADDRESS' as satellite, col as sat_column,
       count(*)              as compared,
       count_if(cls = 0)     as exact,
       count_if(cls = 1)     as trimmed_or_blank_to_null,
       count_if(cls = 2)     as typed_value_kept_text_differs,
       count_if(cls = 3)     as reformatted,
       count_if(cls = 4)     as decimals_lost,
       count_if(cls = 5)     as truncated,
       count_if(cls = 6)     as different_value,
       case when count_if(cls in (3, 4, 5)) > 0 then 'FAIL'
            when count_if(cls = 6) > 0 then 'REVIEW (value differs - see DM-A2)'
            when count_if(cls = 1) > 0 then 'PASS (whitespace / blank->null by design)'
            else 'PASS' end  as format_status
  from best
 group by col
 order by col;



----------------------------------------------------------------------------------------
-- 3. MAXIMUS — SAT_COMMON_ADMIN_GEOGRAPHY   [Implemented]
-- 1 mapped column(s), 1 RAW column lineage row(s); 1 column(s) are 1:1 and value-checked
-- in (b). 1 RAW branch(es):
-- BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW.
----------------------------------------------------------------------------------------
-- SQL query (a) -- column type / length / precision / scale: RAW vs satellite
with lineage (sat_column, raw_db, raw_schema, raw_table, raw_column, transform_flags, transform) as (
    -- generated from the dbt models: every RAW column that feeds a satellite column
    select * from values
        ('CITYCLASSCODE', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'CITY_CLASS', 'TRIM, BLANK->NULL', 'nullif(trim(to_varchar("CITY_CLASS")), '''')')
),
raw_cols as (
    select table_catalog, table_schema, table_name, column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PROD_MIRROR_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'MAXI_RAW'
       and table_name in ('BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW')
),
sat_cols as (
    select column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'BGIL_DATA_MODEL'
       and table_name = 'SAT_COMMON_ADMIN_GEOGRAPHY'
)
select 'MAXIMUS' as project, 'SAT_COMMON_ADMIN_GEOGRAPHY' as satellite,
       l.sat_column, case when s.data_type = 'TEXT' then 'TEXT(' || s.char_len || ')' when s.data_type = 'NUMBER' then 'NUMBER(' || s.num_prec || ',' || s.num_scale || ')' when s.data_type like 'TIMESTAMP%' then s.data_type || '(' || s.dt_prec || ')' else s.data_type end as sat_type,
       l.raw_table, l.raw_column, case when r.data_type = 'TEXT' then 'TEXT(' || r.char_len || ')' when r.data_type = 'NUMBER' then 'NUMBER(' || r.num_prec || ',' || r.num_scale || ')' when r.data_type like 'TIMESTAMP%' then r.data_type || '(' || r.dt_prec || ')' else r.data_type end as raw_type,
       l.transform_flags,
       case
         when r.data_type is null then 'FAIL - RAW COLUMN NOT FOUND'
         when s.data_type is null then 'FAIL - SAT COLUMN NOT FOUND'
         when r.data_type = 'NUMBER' and r.num_scale > 0 and l.transform_flags like '%SCALE0%'
              then 'FAIL - DECIMALS LOST (cast to integer NUMBER on load)'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER' and s.num_scale < r.num_scale then 'FAIL - DECIMALS LOST'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER'
              and s.num_prec - s.num_scale < r.num_prec - r.num_scale then 'FAIL - PRECISION RISK'
         when r.data_type = 'TEXT' and s.data_type = 'TEXT' and s.char_len < r.char_len then 'FAIL - TRUNCATION RISK (length)'
         when r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%' and s.dt_prec < r.dt_prec
              then 'FAIL - FRACTIONAL SECONDS TRUNCATED'
         when r.data_type = 'DATE' and s.data_type like 'TIMESTAMP%' then 'REVIEW - DATE LOADED AS TIMESTAMP'
         when r.data_type <> 'TEXT' and s.data_type = 'TEXT' then 'REVIEW - STORED AS TEXT (see query b)'
         when r.data_type = 'TEXT' and s.data_type <> 'TEXT' then 'REVIEW - TEXT CONVERTED TO ' || s.data_type
         when r.data_type <> s.data_type and not (r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%')
              then 'REVIEW - TYPE CHANGED'
         when l.transform_flags like '%TRIM%' then 'PASS (whitespace trimmed by design)'
         else 'PASS'
       end as type_verdict,
       l.transform
  from lineage l
