        ('PARTYSTATUS', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL', 'PARTY_STATUS', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("PARTY_STATUS")), '''')'),
