        ('SALUTATION', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL', 'TITLE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("TITLE")), '''')'),
        ('AGE', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'AGE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("AGE")), '''')'),
        ('COUNTRYOFBIRTH', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'COUNTRY_OF_BIRTH', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("COUNTRY_OF_BIRTH")), '''')'),
        ('COUNTRYOFRESIDENCE', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'COUNTRY_OF_RESIDENCE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("COUNTRY_OF_RESIDENCE")), '''')'),
        ('DATEOFBIRTH', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'DATE_OF_BIRTH', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("DATE_OF_BIRTH")), '''')'),
