        ('LASTNAME', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'LAST_NAME', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("LAST_NAME")), '''')'),
