-- 35. MAXIMUS — SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS   [Implemented]
-- 11 mapped column(s), 12 RAW column lineage row(s); 11 column(s) are 1:1 and
-- value-checked in (b). 2 RAW branch(es): BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL,
-- BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW.
----------------------------------------------------------------------------------------
-- SQL query (a) -- column type / length / precision / scale: RAW vs satellite
with lineage (sat_column, raw_db, raw_schema, raw_table, raw_column, transform_flags, transform) as (
    -- generated from the dbt models: every RAW column that feeds a satellite column
    select * from values
        ('OCCUPATIONCODE', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL', 'OCCUPATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("OCCUPATION")), '''')'),
        ('ANNUALINCOME', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'MONTHLY_INCOME', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("MONTHLY_INCOME")), '''')'),
        ('DESIGNATION', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'DESIGNATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("DESIGNATION")), '''')'),
        ('EDUCATIONALQUALIFICATION', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'EDUCATIONAL_QUALIFICATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("EDUCATIONAL_QUALIFICATION")), '''')'),
        ('FATHERNAME', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'FATHER_NAME', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("FATHER_NAME")), '''')'),
        ('HIGHESTDEGREE', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'HIGHEST_QUALIFICATION_DETAILS', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("HIGHEST_QUALIFICATION_DETAILS")), '''')'),
        ('MARITALSTATUS', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'MARITAL_STATUS', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("MARITAL_STATUS")), '''')'),
        ('OCCUPATIONCODE', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'OCCUPATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("OCCUPATION")), '''')'),
        ('OCCUPATIONDESCRIPTION', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'PRIMARY_PROFESSION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("PRIMARY_PROFESSION")), '''')'),
        ('SPOUSENAME', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'SPOUSE_NAME', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("SPOUSE_NAME")), '''')'),
        ('VEHICLEOWNEDINDICATOR', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'DO_YOU_HAVE_2_WHEELER4_WHEELER', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("DO_YOU_HAVE_2_WHEELER4_WHEELER")), '''')'),
        ('YEARSINCITY', 'BAGIC_PROD_MIRROR_DB', 'MAXI_RAW', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'NUMBER_OF_YEARS_RESIDING_IN_THE_CITY_OF_RESIDENCE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar("NUMBER_OF_YEARS_RESIDING_IN_THE_CITY_OF_RESIDENCE")), '''')')
),
raw_cols as (
    select table_catalog, table_schema, table_name, column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PROD_MIRROR_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'MAXI_RAW'
       and table_name in ('BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL', 'BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW')
),
sat_cols as (
    select column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'BGIL_DATA_MODEL'
       and table_name = 'SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS'
)
select 'MAXIMUS' as project, 'SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS' as satellite,
       l.sat_column, case when s.data_type = 'TEXT' then 'TEXT(' || s.char_len || ')' when s.data_type = 'NUMBER' then 'NUMBER(' || s.num_prec || ',' || s.num_scale || ')' when s.data_type like 'TIMESTAMP%' then s.data_type || '(' || s.dt_prec || ')' else s.data_type end as sat_type,
       l.raw_table, l.raw_column, case when r.data_type = 'TEXT' then 'TEXT(' || r.char_len || ')' when r.data_type = 'NUMBER' then 'NUMBER(' || r.num_prec || ',' || r.num_scale || ')' when r.data_type like 'TIMESTAMP%' then r.data_type || '(' || r.dt_prec || ')' else r.data_type end as raw_type,
       l.transform_flags,
       case
         when r.data_type is null then 'FAIL - RAW COLUMN NOT FOUND'
         when s.data_type is null then 'FAIL - SAT COLUMN NOT FOUND'
         when r.data_type = 'NUMBER' and r.num_scale > 0 and l.transform_flags like '%SCALE0%'
              then 'FAIL - DECIMALS LOST (cast to integer NUMBER on load)'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER' and s.num_scale < r.num_scale then 'FAIL - DECIMALS LOST'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER'
              and s.num_prec - s.num_scale < r.num_prec - r.num_scale then 'FAIL - PRECISION RISK'
         when r.data_type = 'TEXT' and s.data_type = 'TEXT' and s.char_len < r.char_len then 'FAIL - TRUNCATION RISK (length)'
         when r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%' and s.dt_prec < r.dt_prec
              then 'FAIL - FRACTIONAL SECONDS TRUNCATED'
         when r.data_type = 'DATE' and s.data_type like 'TIMESTAMP%' then 'REVIEW - DATE LOADED AS TIMESTAMP'
         when r.data_type <> 'TEXT' and s.data_type = 'TEXT' then 'REVIEW - STORED AS TEXT (see query b)'
         when r.data_type = 'TEXT' and s.data_type <> 'TEXT' then 'REVIEW - TEXT CONVERTED TO ' || s.data_type
         when r.data_type <> s.data_type and not (r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%')
              then 'REVIEW - TYPE CHANGED'
         when l.transform_flags like '%TRIM%' then 'PASS (whitespace trimmed by design)'
         else 'PASS'
       end as type_verdict,
       l.transform
  from lineage l
  left join raw_cols r
         on r.table_catalog = l.raw_db and r.table_schema = l.raw_schema
        and r.table_name = l.raw_table and r.column_name = l.raw_column
  left join sat_cols s on s.column_name = l.sat_column
 order by l.sat_column, l.raw_table, l.raw_column;

