    select s.PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'BUSINESSREGISTRATIONNUMBER', to_varchar(s."BUSINESSREGISTRATIONNUMBER"),
               'DATEOFINCORPORATION', to_varchar(s."DATEOFINCORPORATION"),
               'LEGALCONSTITUTIONTYPE', to_varchar(s."LEGALCONSTITUTIONTYPE"),
