               'SURCHARGEPERCENTAGE', to_varchar(s."SURCHARGEPERCENTAGE"),
               'TARIFFDOCUMENTREFERENCE', to_varchar(s."TARIFFDOCUMENTREFERENCE"),
               'TARIFFDOCUMENTSAVAILABLEINDICATOR', to_varchar(s."TARIFFDOCUMENTSAVAILABLEINDICATOR"),
               'TARIFFLINEREMARKS', to_varchar(s."TARIFFLINEREMARKS"),
               'TARIFFMASTERUPLOADEDINDICATOR', to_varchar(s."TARIFFMASTERUPLOADEDINDICATOR"),
               'TARIFFSTANDARDISEDINDICATOR', to_varchar(s."TARIFFSTANDARDISEDINDICATOR")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PROVIDER_TARIFF s
     where startswith(s.RECORD_SOURCE, 'MAXIMUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
raw_vals as (
    -- 1. BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) as hkey,
           'MAXIMUS_pd_prop_sp_pv' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW,
           lateral flatten(input => object_construct_keep_null(
                                     'DELAYEDSUBMISSIONDISCOUNTAPPLICABLEINDICATOR', array_construct(to_varchar("DELAYED_SUBMISSION_DISCOUNT_APPLICABLE"), typeof(to_variant("DELAYED_SUBMISSION_DISCOUNT_APPLICABLE"))),
                                     'DISCOUNTANDLOADINGTERMS', array_construct(to_varchar("DISCOUNT_AND_LOADING"), typeof(to_variant("DISCOUNT_AND_LOADING"))),
                                     'DISCOUNTTYPE', array_construct(to_varchar("DISCOUNT_TYPE"), typeof(to_variant("DISCOUNT_TYPE"))),
                                     'FLATRATEBASISINDICATOR', array_construct(to_varchar("FLAT_RATE_BASIS"), typeof(to_variant("FLAT_RATE_BASIS"))),
                                     'HOSPITALSPECIFICBILLITEMCODE', array_construct(to_varchar("HOSPITAL_SPECIIFIC_ITEM_CODES_IN_BILL"), typeof(to_variant("HOSPITAL_SPECIIFIC_ITEM_CODES_IN_BILL"))),
                                     'NEGOTIATIONENDDATE', array_construct(to_varchar("HOSPITAL_TARIFF_UNDER_NEGOTIATION_END_DATE"), typeof(to_variant("HOSPITAL_TARIFF_UNDER_NEGOTIATION_END_DATE"))),
                                     'NEGOTIATIONREMARKS', array_construct(to_varchar("HOSPITAL_TARIFF_UNDER_NEGOTIATION_REMARKS"), typeof(to_variant("HOSPITAL_TARIFF_UNDER_NEGOTIATION_REMARKS"))),
                                     'NEGOTIATIONSTARTDATE', array_construct(to_varchar("HOSPITAL_TARIFF_UNDER_NEGOTIATION_START_DATE"), typeof(to_variant("HOSPITAL_TARIFF_UNDER_NEGOTIATION_START_DATE"))),
                                     'PACKAGEACCEPTANCEDATE', array_construct(to_varchar("PACKAGE_ACCEPTANCE_DATE"), typeof(to_variant("PACKAGE_ACCEPTANCE_DATE"))),
                                     'PACKAGETYPE', array_construct(to_varchar("PACKAGE_TYPE"), typeof(to_variant("PACKAGE_TYPE"))),
                                     'STEPDOWNAPPLICABLEINDICATOR', array_construct(to_varchar("STEP_DOWN_APPLICABLE"), typeof(to_variant("STEP_DOWN_APPLICABLE"))),
                                     'SURCHARGEPERCENTAGE', array_construct(to_varchar("SURCHARGE"), typeof(to_variant("SURCHARGE"))),
                                     'TARIFFDOCUMENTREFERENCE', array_construct(to_varchar("HOSPITAL_TARIFF_DOCS"), typeof(to_variant("HOSPITAL_TARIFF_DOCS"))),
                                     'TARIFFDOCUMENTSAVAILABLEINDICATOR', array_construct(to_varchar("VIEW_TARIFF_DOCS"), typeof(to_variant("VIEW_TARIFF_DOCS"))),
                                     'TARIFFLINEREMARKS', array_construct(to_varchar("STEP_DOWN_OPTION_FOR_ROOM_RENT_REMARKS"), typeof(to_variant("STEP_DOWN_OPTION_FOR_ROOM_RENT_REMARKS"))),
                                     'TARIFFMASTERUPLOADEDINDICATOR', array_construct(to_varchar("TARIFF_MASTER_UPLOAD"), typeof(to_variant("TARIFF_MASTER_UPLOAD"))),
                                     'TARIFFSTANDARDISEDINDICATOR', array_construct(to_varchar("TARIFF_STANDARDIZATION"), typeof(to_variant("TARIFF_STANDARDIZATION")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
),
classified as (
    select v.hkey, v.rs, v.col,
           case
             when equal_null(v.val, r.raw_value) then 0                                                  -- EXACT
             when v.val is null and nullif(trim(r.raw_value), '') is null then 1                         -- BLANK -> NULL (by design)
             when v.val = trim(r.raw_value) then 1                                                       -- WHITESPACE TRIMMED (by design)
             when r.raw_type <> 'VARCHAR' and v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 2             -- TYPED VALUE KEPT, TEXT FORM DIFFERS
             when r.raw_type <> 'VARCHAR' and try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 2
             when v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 3             -- DATE/TIME RE-FORMATTED
             when try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 3             -- NUMBER RE-FORMATTED
             when try_to_decimal(r.raw_value, 38, 12) <> round(try_to_decimal(r.raw_value, 38, 12), 0)
                  and try_to_decimal(v.val, 38, 12) = round(try_to_decimal(r.raw_value, 38, 12), 0) then 4  -- DECIMALS LOST
             when startswith(r.raw_value, v.val) then 5                                                  -- TRUNCATED
             else 6                                                                            -- DIFFERENT VALUE
           end as cls
      from sat_cols v
      join raw_vals r on r.hkey = v.hkey and r.rs_key = v.rs_key and r.col = v.col
),
best as (
    -- a key can have several RAW rows: keep the closest one per (unit, column)
    select hkey, rs, col, min(cls) as cls from classified group by hkey, rs, col
)
select 'MAXIMUS' as project, 'SAT_AUG_PROVIDER_TARIFF' as satellite, col as sat_column,
       count(*)              as compared,
       count_if(cls = 0)     as exact,
       count_if(cls = 1)     as trimmed_or_blank_to_null,
       count_if(cls = 2)     as typed_value_kept_text_differs,
       count_if(cls = 3)     as reformatted,
       count_if(cls = 4)     as decimals_lost,
       count_if(cls = 5)     as truncated,
       count_if(cls = 6)     as different_value,
       case when count_if(cls in (3, 4, 5)) > 0 then 'FAIL'
            when count_if(cls = 6) > 0 then 'REVIEW (value differs - see DM-A2)'
            when count_if(cls = 1) > 0 then 'PASS (whitespace / blank->null by design)'
            else 'PASS' end  as format_status
  from best
 group by col
 order by col;



