                                     'ADDRESSLINE2', array_construct(to_varchar("PARENT_CO_ADD_LINE2"), typeof(to_variant("PARENT_CO_ADD_LINE2"))),
                                     'ADDRESSLINE3', array_construct(to_varchar("PARENT_CO_ADD_LINE3"), typeof(to_variant("PARENT_CO_ADD_LINE3"))),
