    -- 12. BJAZ_T_EKYC (stitch stitch_kyc_common_address t6)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (case when nullif(upper(trim(to_varchar(nullif(trim("COUNTRY"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("HOUSE_NUMBER"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("PIN_CODE"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("STATE"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("STREET"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("VTC_NAME"::varchar), '')))), '') is not null then coalesce(nullif(upper(trim(to_varchar(nullif(trim("HOUSE_NUMBER"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("STREET"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("LANDMARK"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("LOCATION"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("POST_OFFICE"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("SUB_DISTRICT"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("VTC_NAME"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("DISTRICT"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("STATE"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("COUNTRY"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("PIN_CODE"::varchar), '')))), ''), '') end)) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_EKYC,
           lateral flatten(input => object_construct_keep_null(
                                     'CITY', array_construct(to_varchar("VTC_NAME"), typeof(to_variant("VTC_NAME"))),
                                     'COUNTRYNAME', array_construct(to_varchar("COUNTRY"), typeof(to_variant("COUNTRY"))),
                                     'DOORNUMBER', array_construct(to_varchar("HOUSE_NUMBER"), typeof(to_variant("HOUSE_NUMBER"))),
                                     'POSTALCODE', array_construct(to_varchar("PIN_CODE"), typeof(to_variant("PIN_CODE"))),
                                     'STATENAME', array_construct(to_varchar("STATE"), typeof(to_variant("STATE"))),
                                     'STREETNAME', array_construct(to_varchar("STREET"), typeof(to_variant("STREET")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 13. BJAZ_T_KYC_OCR (stitch stitch_kyc_common_address t7)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (case when nullif(upper(trim(to_varchar(nullif(trim("BUILDING"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("COUNTRY_CODE"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("HOUSE_NUMBER"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("PIN_CODE"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("STATE"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("STREET"::varchar), '')))), '') is not null then coalesce(nullif(upper(trim(to_varchar(nullif(trim("HOUSE_NUMBER"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("BUILDING"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("STREET"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("LOCATION"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("POST_OFFICE"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("DISTRICT"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("STATE"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("PIN_CODE"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("COUNTRY_CODE"::varchar), '')))), ''), '') end)) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_OCR,
           lateral flatten(input => object_construct_keep_null(
                                     'BUILDINGNAME', array_construct(to_varchar("BUILDING"), typeof(to_variant("BUILDING"))),
                                     'COUNTRYCODE', array_construct(to_varchar("COUNTRY_CODE"), typeof(to_variant("COUNTRY_CODE"))),
                                     'DOORNUMBER', array_construct(to_varchar("HOUSE_NUMBER"), typeof(to_variant("HOUSE_NUMBER"))),
                                     'POSTALCODE', array_construct(to_varchar("PIN_CODE"), typeof(to_variant("PIN_CODE"))),
                                     'STATENAME', array_construct(to_varchar("STATE"), typeof(to_variant("STATE"))),
                                     'STREETNAME', array_construct(to_varchar("STREET"), typeof(to_variant("STREET")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
),
classified as (
    select v.hkey, v.rs, v.col,
           case
             when equal_null(v.val, r.raw_value) then 0                                                  -- EXACT
             when v.val is null and nullif(trim(r.raw_value), '') is null then 1                         -- BLANK -> NULL (by design)
             when v.val = trim(r.raw_value) then 1                                                       -- WHITESPACE TRIMMED (by design)
             when r.raw_type <> 'VARCHAR' and v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 2             -- TYPED VALUE KEPT, TEXT FORM DIFFERS
             when r.raw_type <> 'VARCHAR' and try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 2
             when v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 3             -- DATE/TIME RE-FORMATTED
             when try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 3             -- NUMBER RE-FORMATTED
             when try_to_decimal(r.raw_value, 38, 12) <> round(try_to_decimal(r.raw_value, 38, 12), 0)
                  and try_to_decimal(v.val, 38, 12) = round(try_to_decimal(r.raw_value, 38, 12), 0) then 4  -- DECIMALS LOST
             when startswith(r.raw_value, v.val) then 5                                                  -- TRUNCATED
             else 6                                                                            -- DIFFERENT VALUE
           end as cls
      from sat_cols v
      join raw_vals r on r.hkey = v.hkey and r.rs_key = v.rs_key and r.col = v.col
),
best as (
    -- a key can have several RAW rows: keep the closest one per (unit, column)
    select hkey, rs, col, min(cls) as cls from classified group by hkey, rs, col
)
select 'OPUS' as project, 'SAT_COMMON_ADDRESS' as satellite, col as sat_column,
       count(*)              as compared,
       count_if(cls = 0)     as exact,
       count_if(cls = 1)     as trimmed_or_blank_to_null,
       count_if(cls = 2)     as typed_value_kept_text_differs,
       count_if(cls = 3)     as reformatted,
       count_if(cls = 4)     as decimals_lost,
       count_if(cls = 5)     as truncated,
       count_if(cls = 6)     as different_value,
       case when count_if(cls in (3, 4, 5)) > 0 then 'FAIL'
            when count_if(cls = 6) > 0 then 'REVIEW (value differs - see DM-A2)'
            when count_if(cls = 1) > 0 then 'PASS (whitespace / blank->null by design)'
            else 'PASS' end  as format_status
  from best
 group by col
 order by col;



