sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
raw_vals as (
    -- 1. BJAZ_T_CKYC_PERSONAL_DTLS
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce(nullif(trim("CKYC_NO"::varchar), ''),''))), 'CKYC:'))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_PERSONAL_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'CONSENTDATE', array_construct(to_varchar("DEC_DATE"), typeof(to_variant("DEC_DATE")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
),
classified as (
    select v.hkey, v.rs, v.col,
           case
             when equal_null(v.val, r.raw_value) then 0                                                  -- EXACT
             when v.val is null and nullif(trim(r.raw_value), '') is null then 1                         -- BLANK -> NULL (by design)
             when v.val = trim(r.raw_value) then 1                                                       -- WHITESPACE TRIMMED (by design)
             when r.raw_type <> 'VARCHAR' and v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 2             -- TYPED VALUE KEPT, TEXT FORM DIFFERS
             when r.raw_type <> 'VARCHAR' and try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 2
             when v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 3             -- DATE/TIME RE-FORMATTED
             when try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 3             -- NUMBER RE-FORMATTED
             when try_to_decimal(r.raw_value, 38, 12) <> round(try_to_decimal(r.raw_value, 38, 12), 0)
                  and try_to_decimal(v.val, 38, 12) = round(try_to_decimal(r.raw_value, 38, 12), 0) then 4  -- DECIMALS LOST
             when startswith(r.raw_value, v.val) then 5                                                  -- TRUNCATED
             else 6                                                                            -- DIFFERENT VALUE
           end as cls
      from sat_cols v
      join raw_vals r on r.hkey = v.hkey and r.rs_key = v.rs_key and r.col = v.col
),
best as (
    -- a key can have several RAW rows: keep the closest one per (unit, column)
    select hkey, rs, col, min(cls) as cls from classified group by hkey, rs, col
)
select 'OPUS' as project, 'SAT_COMMON_CONSENT' as satellite, col as sat_column,
       count(*)              as compared,
       count_if(cls = 0)     as exact,
       count_if(cls = 1)     as trimmed_or_blank_to_null,
       count_if(cls = 2)     as typed_value_kept_text_differs,
       count_if(cls = 3)     as reformatted,
       count_if(cls = 4)     as decimals_lost,
       count_if(cls = 5)     as truncated,
       count_if(cls = 6)     as different_value,
       case when count_if(cls in (3, 4, 5)) > 0 then 'FAIL'
            when count_if(cls = 6) > 0 then 'REVIEW (value differs - see DM-A2)'
            when count_if(cls = 1) > 0 then 'PASS (whitespace / blank->null by design)'
            else 'PASS' end  as format_status
  from best
 group by col
 order by col;



----------------------------------------------------------------------------------------
-- 106. OPUS — SAT_COMMON_CONTACT   [Implemented]
-- 8 mapped column(s), 27 RAW column lineage row(s); 8 column(s) are 1:1 and
-- value-checked in (b). Static transform flags -- integer cast on load (decimals lost if
-- the RAW column has a scale): MOBILENUMBER<-SUPP_MOBILE, MOBILENUMBER<-MOBILE_NO. 12
-- RAW branch(es): AZBJ_PARTNER_EXTN, BJAZ_CLM_SUPP_EXTN, BJAZ_CTNGY_GC_MEM_DATA,
-- BJAZ_CTNGY_PA_MEM_DTLS, BJAZ_HM_HOSPITAL_MASTER, BJAZ_HM_MEMBER_DTLS,
-- BJAZ_SH_MEM_DTLS_EXTN, CLM_SUPPLIERS, CP_PARTNERS, BJAZ_T_CKYC_OTP, BJAZ_T_EKYC,
-- BJAZ_T_KYC_DETAILS.
----------------------------------------------------------------------------------------
-- SQL query (a) -- column type / length / precision / scale: RAW vs satellite
with lineage (sat_column, raw_db, raw_schema, raw_table, raw_column, transform_flags, transform) as (
    -- generated from the dbt models: every RAW column that feeds a satellite column
    select * from values
        ('ALTERNATEEMAILADDRESS', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'AZBJ_PARTNER_EXTN', 'EMAIL_2', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("EMAIL_2"::varchar), '''')'),
        ('ALTERNATEMOBILENUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'AZBJ_PARTNER_EXTN', 'ALT_MOBILE_NO', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("ALT_MOBILE_NO"::varchar), '''')'),
        ('LANDLINENUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'AZBJ_PARTNER_EXTN', 'TELEPHONE3', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("TELEPHONE3"::varchar), '''')'),
        ('PREFERREDCONTACTTIME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'AZBJ_PARTNER_EXTN', 'PREFERRED_CONTACT_OPT', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PREFERRED_CONTACT_OPT"::varchar), '''')'),
        ('EMAILADDRESS', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CLM_SUPP_EXTN', 'SUPP_EMAIL', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("SUPP_EMAIL"::varchar), '''')'),
        ('LANDLINENUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CLM_SUPP_EXTN', 'PHONE_DETAILS', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PHONE_DETAILS"::varchar), '''')'),
        ('MOBILENUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CLM_SUPP_EXTN', 'SUPP_MOBILE', 'SCALE0, SAT_VARCHAR', '("SUPP_MOBILE"::number)'),
        ('STDCODE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CLM_SUPP_EXTN', 'STD_CODE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("STD_CODE"::varchar), '''')'),
        ('LANDLINENUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CTNGY_GC_MEM_DATA', 'TELEPHONE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("TELEPHONE"::varchar), '''')'),
        ('EMAILADDRESS', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CTNGY_PA_MEM_DTLS', 'EMAIL_ID', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("EMAIL_ID"::varchar), '''')'),
        ('FAXNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CTNGY_PA_MEM_DTLS', 'FAX', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("FAX"::varchar), '''')'),
        ('LANDLINENUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CTNGY_PA_MEM_DTLS', 'TELEPHONE_NO', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("TELEPHONE_NO"::varchar), '''')'),
        ('MOBILENUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CTNGY_PA_MEM_DTLS', 'MOBILE_NO', 'SCALE0, SAT_VARCHAR', '("MOBILE_NO"::number)'),
        ('EMAILADDRESS', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HM_HOSPITAL_MASTER', 'EMAIL', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("EMAIL"::varchar), '''')'),
        ('FAXNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HM_HOSPITAL_MASTER', 'FAX_NO', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("FAX_NO"::varchar), '''')'),
        ('LANDLINENUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HM_HOSPITAL_MASTER', 'PHONE_NO', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PHONE_NO"::varchar), '''')'),
        ('STDCODE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HM_HOSPITAL_MASTER', 'STD_CODE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("STD_CODE"::varchar), '''')'),
        ('EMAILADDRESS', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HM_MEMBER_DTLS', 'EMAIL_ID', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("EMAIL_ID"::varchar), '''')'),
        ('LANDLINENUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HM_MEMBER_DTLS', 'PHONE_NO', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PHONE_NO"::varchar), '''')'),
        ('EMAILADDRESS', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SH_MEM_DTLS_EXTN', 'EMAIL_ID', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("EMAIL_ID"::varchar), '''')'),
        ('LANDLINENUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'CLM_SUPPLIERS', 'CONTACT', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("CONTACT"::varchar), '''')'),
        ('EMAILADDRESS', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'CP_PARTNERS', 'EMAIL', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("EMAIL"::varchar), '''')'),
        ('FAXNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'CP_PARTNERS', 'FAX', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("FAX"::varchar), '''')'),
        ('LANDLINENUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'CP_PARTNERS', 'TELEPHONE2', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("TELEPHONE2"::varchar), '''')'),
        ('MOBILENUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_CKYC_OTP', 'MOBILE_NUMBER', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("MOBILE_NUMBER"::varchar), '''')'),
        ('MOBILENUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_EKYC', 'MOBILE_NUMBER', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("MOBILE_NUMBER"::varchar), '''')'),
        ('MOBILENUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_DETAILS', 'MOBILE_NUMBER', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("MOBILE_NUMBER"::varchar), '''')')
),
raw_cols as (
    select table_catalog, table_schema, table_name, column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'UTILS'
       and table_name in ('AZBJ_PARTNER_EXTN', 'BJAZ_CLM_SUPP_EXTN', 'BJAZ_CTNGY_GC_MEM_DATA', 'BJAZ_CTNGY_PA_MEM_DTLS', 'BJAZ_HM_HOSPITAL_MASTER', 'BJAZ_HM_MEMBER_DTLS', 'BJAZ_SH_MEM_DTLS_EXTN', 'BJAZ_T_CKYC_OTP', 'BJAZ_T_EKYC', 'BJAZ_T_KYC_DETAILS', 'CLM_SUPPLIERS', 'CP_PARTNERS')
),
sat_cols as (
    select column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'BGIL_DATA_MODEL'
       and table_name = 'SAT_COMMON_CONTACT'
)
select 'OPUS' as project, 'SAT_COMMON_CONTACT' as satellite,
       l.sat_column, case when s.data_type = 'TEXT' then 'TEXT(' || s.char_len || ')' when s.data_type = 'NUMBER' then 'NUMBER(' || s.num_prec || ',' || s.num_scale || ')' when s.data_type like 'TIMESTAMP%' then s.data_type || '(' || s.dt_prec || ')' else s.data_type end as sat_type,
       l.raw_table, l.raw_column, case when r.data_type = 'TEXT' then 'TEXT(' || r.char_len || ')' when r.data_type = 'NUMBER' then 'NUMBER(' || r.num_prec || ',' || r.num_scale || ')' when r.data_type like 'TIMESTAMP%' then r.data_type || '(' || r.dt_prec || ')' else r.data_type end as raw_type,
       l.transform_flags,
       case
         when r.data_type is null then 'FAIL - RAW COLUMN NOT FOUND'
         when s.data_type is null then 'FAIL - SAT COLUMN NOT FOUND'
         when r.data_type = 'NUMBER' and r.num_scale > 0 and l.transform_flags like '%SCALE0%'
              then 'FAIL - DECIMALS LOST (cast to integer NUMBER on load)'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER' and s.num_scale < r.num_scale then 'FAIL - DECIMALS LOST'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER'
              and s.num_prec - s.num_scale < r.num_prec - r.num_scale then 'FAIL - PRECISION RISK'
         when r.data_type = 'TEXT' and s.data_type = 'TEXT' and s.char_len < r.char_len then 'FAIL - TRUNCATION RISK (length)'
         when r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%' and s.dt_prec < r.dt_prec
              then 'FAIL - FRACTIONAL SECONDS TRUNCATED'
         when r.data_type = 'DATE' and s.data_type like 'TIMESTAMP%' then 'REVIEW - DATE LOADED AS TIMESTAMP'
         when r.data_type <> 'TEXT' and s.data_type = 'TEXT' then 'REVIEW - STORED AS TEXT (see query b)'
         when r.data_type = 'TEXT' and s.data_type <> 'TEXT' then 'REVIEW - TEXT CONVERTED TO ' || s.data_type
         when r.data_type <> s.data_type and not (r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%')
              then 'REVIEW - TYPE CHANGED'
         when l.transform_flags like '%TRIM%' then 'PASS (whitespace trimmed by design)'
         else 'PASS'
       end as type_verdict,
       l.transform
  from lineage l
  left join raw_cols r
         on r.table_catalog = l.raw_db and r.table_schema = l.raw_schema
        and r.table_name = l.raw_table and r.column_name = l.raw_column
  left join sat_cols s on s.column_name = l.sat_column
 order by l.sat_column, l.raw_table, l.raw_column;

-- SQL query (b) -- value format on the sample (1:1 mapped columns; run the ALTER SESSION first)
alter session set TIMESTAMP_NTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9',
                  TIMESTAMP_LTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  TIMESTAMP_TZ_OUTPUT_FORMAT  = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  DATE_OUTPUT_FORMAT          = 'YYYY-MM-DD';

with sat_rows as (
    -- this project's rows of the satellite
    select s.PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'ALTERNATEEMAILADDRESS', to_varchar(s."ALTERNATEEMAILADDRESS"),
               'ALTERNATEMOBILENUMBER', to_varchar(s."ALTERNATEMOBILENUMBER"),
               'LANDLINENUMBER', to_varchar(s."LANDLINENUMBER"),
               'PREFERREDCONTACTTIME', to_varchar(s."PREFERREDCONTACTTIME"),
               'EMAILADDRESS', to_varchar(s."EMAILADDRESS"),
               'MOBILENUMBER', to_varchar(s."MOBILENUMBER"),
               'STDCODE', to_varchar(s."STDCODE"),
               'FAXNUMBER', to_varchar(s."FAXNUMBER")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_CONTACT s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
raw_vals as (
    -- 1. AZBJ_PARTNER_EXTN
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'ALTERNATEEMAILADDRESS', array_construct(to_varchar("EMAIL_2"), typeof(to_variant("EMAIL_2"))),
                                     'ALTERNATEMOBILENUMBER', array_construct(to_varchar("ALT_MOBILE_NO"), typeof(to_variant("ALT_MOBILE_NO"))),
                                     'LANDLINENUMBER', array_construct(to_varchar("TELEPHONE3"), typeof(to_variant("TELEPHONE3"))),
                                     'PREFERREDCONTACTTIME', array_construct(to_varchar("PREFERRED_CONTACT_OPT"), typeof(to_variant("PREFERRED_CONTACT_OPT")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_CLM_SUPP_EXTN
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'EMAILADDRESS', array_construct(to_varchar("SUPP_EMAIL"), typeof(to_variant("SUPP_EMAIL"))),
                                     'LANDLINENUMBER', array_construct(to_varchar("PHONE_DETAILS"), typeof(to_variant("PHONE_DETAILS"))),
                                     'MOBILENUMBER', array_construct(to_varchar("SUPP_MOBILE"), typeof(to_variant("SUPP_MOBILE"))),
                                     'STDCODE', array_construct(to_varchar("STD_CODE"), typeof(to_variant("STD_CODE")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BJAZ_CTNGY_GC_MEM_DATA
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_GC_MEM_DATA,
           lateral flatten(input => object_construct_keep_null(
                                     'LANDLINENUMBER', array_construct(to_varchar("TELEPHONE"), typeof(to_variant("TELEPHONE")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 4. BJAZ_CTNGY_PA_MEM_DTLS
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'EMAILADDRESS', array_construct(to_varchar("EMAIL_ID"), typeof(to_variant("EMAIL_ID"))),
                                     'FAXNUMBER', array_construct(to_varchar("FAX"), typeof(to_variant("FAX"))),
                                     'LANDLINENUMBER', array_construct(to_varchar("TELEPHONE_NO"), typeof(to_variant("TELEPHONE_NO"))),
                                     'MOBILENUMBER', array_construct(to_varchar("MOBILE_NO"), typeof(to_variant("MOBILE_NO")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 5. BJAZ_HM_HOSPITAL_MASTER
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("HOSID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_HOSPITAL_MASTER,
           lateral flatten(input => object_construct_keep_null(
                                     'EMAILADDRESS', array_construct(to_varchar("EMAIL"), typeof(to_variant("EMAIL"))),
                                     'FAXNUMBER', array_construct(to_varchar("FAX_NO"), typeof(to_variant("FAX_NO"))),
                                     'LANDLINENUMBER', array_construct(to_varchar("PHONE_NO"), typeof(to_variant("PHONE_NO"))),
                                     'STDCODE', array_construct(to_varchar("STD_CODE"), typeof(to_variant("STD_CODE")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 6. BJAZ_HM_MEMBER_DTLS
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'EMAILADDRESS', array_construct(to_varchar("EMAIL_ID"), typeof(to_variant("EMAIL_ID"))),
                                     'LANDLINENUMBER', array_construct(to_varchar("PHONE_NO"), typeof(to_variant("PHONE_NO")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 7. BJAZ_SH_MEM_DTLS_EXTN
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'EMAILADDRESS', array_construct(to_varchar("EMAIL_ID"), typeof(to_variant("EMAIL_ID")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 8. CLM_SUPPLIERS
