        ('EXPIRYDATE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_POA_DOCUMENT', 'EXPIRY_DATE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("EXPIRY_DATE"::varchar), '''')'),
        ('STORAGEREFERENCE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_POA_DOCUMENT', 'OMNI_DOC_INDEX', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("OMNI_DOC_INDEX"::varchar), '''')'),
        ('VERIFICATIONSTATUS', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_POA_DOCUMENT', 'RESPONSE_CODE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("RESPONSE_CODE"::varchar), '''')'),
        ('DOCUMENTCATEGORY', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_POI_DOCUMENT', 'DOCUMENT_CATEGORY', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("DOCUMENT_CATEGORY"::varchar), '''')'),
        ('DOCUMENTFORMAT', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_POI_DOCUMENT', 'DOC_EXTENSION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("DOC_EXTENSION"::varchar), '''')'),
        ('DOCUMENTNAME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_POI_DOCUMENT', 'DOC_NAME', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("DOC_NAME"::varchar), '''')'),
        ('DOCUMENTSTATUS', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_POI_DOCUMENT', 'STATUS', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("STATUS"::varchar), '''')'),
        ('DOCUMENTTYPE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_POI_DOCUMENT', 'DOCS_TYPE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("DOCS_TYPE"::varchar), '''')'),
        ('EXPIRYDATE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_POI_DOCUMENT', 'EXPIRY_DATE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("EXPIRY_DATE"::varchar), '''')'),
        ('STORAGEREFERENCE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_POI_DOCUMENT', 'OMNI_DOC_INDEX', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("OMNI_DOC_INDEX"::varchar), '''')'),
        ('VERIFICATIONSTATUS', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_POI_DOCUMENT', 'RESPONSE_CODE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("RESPONSE_CODE"::varchar), '''')')
),
raw_cols as (
    select table_catalog, table_schema, table_name, column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'UTILS'
       and table_name in ('BJAZ_T_KYC_OCR', 'BJAZ_T_KYC_POA_DOCUMENT', 'BJAZ_T_KYC_POI_DOCUMENT')
),
sat_cols as (
    select column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'BGIL_DATA_MODEL'
       and table_name = 'SAT_DOCUMENT_DEFINITION'
)
select 'OPUS' as project, 'SAT_DOCUMENT_DEFINITION' as satellite,
       l.sat_column, case when s.data_type = 'TEXT' then 'TEXT(' || s.char_len || ')' when s.data_type = 'NUMBER' then 'NUMBER(' || s.num_prec || ',' || s.num_scale || ')' when s.data_type like 'TIMESTAMP%' then s.data_type || '(' || s.dt_prec || ')' else s.data_type end as sat_type,
       l.raw_table, l.raw_column, case when r.data_type = 'TEXT' then 'TEXT(' || r.char_len || ')' when r.data_type = 'NUMBER' then 'NUMBER(' || r.num_prec || ',' || r.num_scale || ')' when r.data_type like 'TIMESTAMP%' then r.data_type || '(' || r.dt_prec || ')' else r.data_type end as raw_type,
       l.transform_flags,
       case
         when r.data_type is null then 'FAIL - RAW COLUMN NOT FOUND'
         when s.data_type is null then 'FAIL - SAT COLUMN NOT FOUND'
         when r.data_type = 'NUMBER' and r.num_scale > 0 and l.transform_flags like '%SCALE0%'
              then 'FAIL - DECIMALS LOST (cast to integer NUMBER on load)'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER' and s.num_scale < r.num_scale then 'FAIL - DECIMALS LOST'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER'
              and s.num_prec - s.num_scale < r.num_prec - r.num_scale then 'FAIL - PRECISION RISK'
         when r.data_type = 'TEXT' and s.data_type = 'TEXT' and s.char_len < r.char_len then 'FAIL - TRUNCATION RISK (length)'
         when r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%' and s.dt_prec < r.dt_prec
              then 'FAIL - FRACTIONAL SECONDS TRUNCATED'
         when r.data_type = 'DATE' and s.data_type like 'TIMESTAMP%' then 'REVIEW - DATE LOADED AS TIMESTAMP'
         when r.data_type <> 'TEXT' and s.data_type = 'TEXT' then 'REVIEW - STORED AS TEXT (see query b)'
         when r.data_type = 'TEXT' and s.data_type <> 'TEXT' then 'REVIEW - TEXT CONVERTED TO ' || s.data_type
         when r.data_type <> s.data_type and not (r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%')
              then 'REVIEW - TYPE CHANGED'
         when l.transform_flags like '%TRIM%' then 'PASS (whitespace trimmed by design)'
         else 'PASS'
       end as type_verdict,
       l.transform
  from lineage l
  left join raw_cols r
         on r.table_catalog = l.raw_db and r.table_schema = l.raw_schema
        and r.table_name = l.raw_table and r.column_name = l.raw_column
  left join sat_cols s on s.column_name = l.sat_column
 order by l.sat_column, l.raw_table, l.raw_column;

-- SQL query (b) -- value format on the sample (1:1 mapped columns; run the ALTER SESSION first)
alter session set TIMESTAMP_NTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9',
                  TIMESTAMP_LTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  TIMESTAMP_TZ_OUTPUT_FORMAT  = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  DATE_OUTPUT_FORMAT          = 'YYYY-MM-DD';

with sat_rows as (
    -- this project's rows of the satellite
    select s.DOCUMENT_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'DOCUMENTCATEGORY', to_varchar(s."DOCUMENTCATEGORY"),
               'DOCUMENTREFERENCENUMBER', to_varchar(s."DOCUMENTREFERENCENUMBER"),
               'DOCUMENTTYPE', to_varchar(s."DOCUMENTTYPE"),
               'VERIFICATIONSTATUS', to_varchar(s."VERIFICATIONSTATUS"),
               'DOCUMENTFORMAT', to_varchar(s."DOCUMENTFORMAT"),
               'DOCUMENTNAME', to_varchar(s."DOCUMENTNAME"),
               'DOCUMENTSTATUS', to_varchar(s."DOCUMENTSTATUS"),
               'EXPIRYDATE', to_varchar(s."EXPIRYDATE"),
               'STORAGEREFERENCE', to_varchar(s."STORAGEREFERENCE")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_DOCUMENT_DEFINITION s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
raw_vals as (
    -- 1. BJAZ_T_KYC_OCR
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_DOCUMENT|' || (upper(trim(nullif(trim("FIELD_TYPE"::varchar), ''))) || ':' || trim(nullif(trim("FIELD_VALUE"::varchar), '')) || '#' || upper(trim(nullif(trim("IMAGE_TYPE"::varchar), ''))))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_KYC_OCR' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_OCR,
           lateral flatten(input => object_construct_keep_null(
                                     'DOCUMENTCATEGORY', array_construct(to_varchar("CATEGORY"), typeof(to_variant("CATEGORY"))),
                                     'DOCUMENTREFERENCENUMBER', array_construct(to_varchar("FILE_NUMBER"), typeof(to_variant("FILE_NUMBER"))),
                                     'DOCUMENTTYPE', array_construct(to_varchar("IMAGE_TYPE"), typeof(to_variant("IMAGE_TYPE"))),
                                     'VERIFICATIONSTATUS', array_construct(to_varchar("OCR_STATUS"), typeof(to_variant("OCR_STATUS")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_T_KYC_POA_DOCUMENT
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_DOCUMENT|' || (upper(trim(coalesce(nullif(trim("DOCS_TYPE"::varchar), ''),''))) || ':' || upper(trim(coalesce(nullif(trim("DOCS_NUMBER"::varchar), ''),''))))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_KYC_POA_DOCUMENT' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_POA_DOCUMENT,
           lateral flatten(input => object_construct_keep_null(
                                     'DOCUMENTCATEGORY', array_construct(to_varchar("DOCUMENT_CATEGORY"), typeof(to_variant("DOCUMENT_CATEGORY"))),
                                     'DOCUMENTFORMAT', array_construct(to_varchar("DOC_EXTENSION"), typeof(to_variant("DOC_EXTENSION"))),
                                     'DOCUMENTNAME', array_construct(to_varchar("DOC_NAME"), typeof(to_variant("DOC_NAME"))),
                                     'DOCUMENTSTATUS', array_construct(to_varchar("STATUS"), typeof(to_variant("STATUS"))),
                                     'DOCUMENTTYPE', array_construct(to_varchar("DOCS_TYPE"), typeof(to_variant("DOCS_TYPE"))),
                                     'EXPIRYDATE', array_construct(to_varchar("EXPIRY_DATE"), typeof(to_variant("EXPIRY_DATE"))),
                                     'STORAGEREFERENCE', array_construct(to_varchar("OMNI_DOC_INDEX"), typeof(to_variant("OMNI_DOC_INDEX"))),
                                     'VERIFICATIONSTATUS', array_construct(to_varchar("RESPONSE_CODE"), typeof(to_variant("RESPONSE_CODE")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BJAZ_T_KYC_POI_DOCUMENT
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_DOCUMENT|' || (upper(trim(coalesce(nullif(trim("DOCS_TYPE"::varchar), ''),''))) || ':' || upper(trim(coalesce(nullif(trim("DOCS_NUMBER"::varchar), ''),''))))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_KYC_POI_DOCUMENT' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_POI_DOCUMENT,
           lateral flatten(input => object_construct_keep_null(
                                     'DOCUMENTCATEGORY', array_construct(to_varchar("DOCUMENT_CATEGORY"), typeof(to_variant("DOCUMENT_CATEGORY"))),
                                     'DOCUMENTFORMAT', array_construct(to_varchar("DOC_EXTENSION"), typeof(to_variant("DOC_EXTENSION"))),
                                     'DOCUMENTNAME', array_construct(to_varchar("DOC_NAME"), typeof(to_variant("DOC_NAME"))),
                                     'DOCUMENTSTATUS', array_construct(to_varchar("STATUS"), typeof(to_variant("STATUS"))),
                                     'DOCUMENTTYPE', array_construct(to_varchar("DOCS_TYPE"), typeof(to_variant("DOCS_TYPE"))),
                                     'EXPIRYDATE', array_construct(to_varchar("EXPIRY_DATE"), typeof(to_variant("EXPIRY_DATE"))),
                                     'STORAGEREFERENCE', array_construct(to_varchar("OMNI_DOC_INDEX"), typeof(to_variant("OMNI_DOC_INDEX"))),
                                     'VERIFICATIONSTATUS', array_construct(to_varchar("RESPONSE_CODE"), typeof(to_variant("RESPONSE_CODE")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
),
classified as (
    select v.hkey, v.rs, v.col,
           case
             when equal_null(v.val, r.raw_value) then 0                                                  -- EXACT
             when v.val is null and nullif(trim(r.raw_value), '') is null then 1                         -- BLANK -> NULL (by design)
             when v.val = trim(r.raw_value) then 1                                                       -- WHITESPACE TRIMMED (by design)
             when r.raw_type <> 'VARCHAR' and v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 2             -- TYPED VALUE KEPT, TEXT FORM DIFFERS
             when r.raw_type <> 'VARCHAR' and try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 2
             when v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 3             -- DATE/TIME RE-FORMATTED
             when try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 3             -- NUMBER RE-FORMATTED
             when try_to_decimal(r.raw_value, 38, 12) <> round(try_to_decimal(r.raw_value, 38, 12), 0)
                  and try_to_decimal(v.val, 38, 12) = round(try_to_decimal(r.raw_value, 38, 12), 0) then 4  -- DECIMALS LOST
             when startswith(r.raw_value, v.val) then 5                                                  -- TRUNCATED
             else 6                                                                            -- DIFFERENT VALUE
           end as cls
      from sat_cols v
      join raw_vals r on r.hkey = v.hkey and r.rs_key = v.rs_key and r.col = v.col
),
best as (
    -- a key can have several RAW rows: keep the closest one per (unit, column)
    select hkey, rs, col, min(cls) as cls from classified group by hkey, rs, col
)
select 'OPUS' as project, 'SAT_DOCUMENT_DEFINITION' as satellite, col as sat_column,
       count(*)              as compared,
       count_if(cls = 0)     as exact,
       count_if(cls = 1)     as trimmed_or_blank_to_null,
       count_if(cls = 2)     as typed_value_kept_text_differs,
       count_if(cls = 3)     as reformatted,
       count_if(cls = 4)     as decimals_lost,
       count_if(cls = 5)     as truncated,
       count_if(cls = 6)     as different_value,
       case when count_if(cls in (3, 4, 5)) > 0 then 'FAIL'
            when count_if(cls = 6) > 0 then 'REVIEW (value differs - see DM-A2)'
            when count_if(cls = 1) > 0 then 'PASS (whitespace / blank->null by design)'
            else 'PASS' end  as format_status
  from best
 group by col
 order by col;



----------------------------------------------------------------------------------------
-- 109. OPUS — SAT_LNK_CLAIM_PARTY_ROLE   [Implemented]
-- 2 mapped column(s), 2 RAW column lineage row(s); 2 column(s) are 1:1 and value-checked
-- in (b). Static transform flags -- integer cast on load (decimals lost if the RAW
-- column has a scale): ROLE_SEQUENCE<-IP_NO. 1 RAW branch(es): CLM_INTERESTED_PARTIES.
----------------------------------------------------------------------------------------
-- SQL query (a) -- column type / length / precision / scale: RAW vs satellite
with lineage (sat_column, raw_db, raw_schema, raw_table, raw_column, transform_flags, transform) as (
    -- generated from the dbt models: every RAW column that feeds a satellite column
    select * from values
        ('PARTY_ROLE_TYPE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'CLM_INTERESTED_PARTIES', 'IP_TYPE', 'TRIM, BLANK->NULL', 'nullif(trim("IP_TYPE"::varchar), '''')'),
        ('ROLE_SEQUENCE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'CLM_INTERESTED_PARTIES', 'IP_NO', 'SCALE0', '("IP_NO"::number)')
),
raw_cols as (
    select table_catalog, table_schema, table_name, column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'UTILS'
       and table_name in ('CLM_INTERESTED_PARTIES')
),
sat_cols as (
    select column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'BGIL_DATA_MODEL'
       and table_name = 'SAT_LNK_CLAIM_PARTY_ROLE'
)
select 'OPUS' as project, 'SAT_LNK_CLAIM_PARTY_ROLE' as satellite,
       l.sat_column, case when s.data_type = 'TEXT' then 'TEXT(' || s.char_len || ')' when s.data_type = 'NUMBER' then 'NUMBER(' || s.num_prec || ',' || s.num_scale || ')' when s.data_type like 'TIMESTAMP%' then s.data_type || '(' || s.dt_prec || ')' else s.data_type end as sat_type,
       l.raw_table, l.raw_column, case when r.data_type = 'TEXT' then 'TEXT(' || r.char_len || ')' when r.data_type = 'NUMBER' then 'NUMBER(' || r.num_prec || ',' || r.num_scale || ')' when r.data_type like 'TIMESTAMP%' then r.data_type || '(' || r.dt_prec || ')' else r.data_type end as raw_type,
       l.transform_flags,
       case
         when r.data_type is null then 'FAIL - RAW COLUMN NOT FOUND'
         when s.data_type is null then 'FAIL - SAT COLUMN NOT FOUND'
         when r.data_type = 'NUMBER' and r.num_scale > 0 and l.transform_flags like '%SCALE0%'
              then 'FAIL - DECIMALS LOST (cast to integer NUMBER on load)'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER' and s.num_scale < r.num_scale then 'FAIL - DECIMALS LOST'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER'
              and s.num_prec - s.num_scale < r.num_prec - r.num_scale then 'FAIL - PRECISION RISK'
         when r.data_type = 'TEXT' and s.data_type = 'TEXT' and s.char_len < r.char_len then 'FAIL - TRUNCATION RISK (length)'
         when r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%' and s.dt_prec < r.dt_prec
              then 'FAIL - FRACTIONAL SECONDS TRUNCATED'
         when r.data_type = 'DATE' and s.data_type like 'TIMESTAMP%' then 'REVIEW - DATE LOADED AS TIMESTAMP'
         when r.data_type <> 'TEXT' and s.data_type = 'TEXT' then 'REVIEW - STORED AS TEXT (see query b)'
         when r.data_type = 'TEXT' and s.data_type <> 'TEXT' then 'REVIEW - TEXT CONVERTED TO ' || s.data_type
         when r.data_type <> s.data_type and not (r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%')
              then 'REVIEW - TYPE CHANGED'
         when l.transform_flags like '%TRIM%' then 'PASS (whitespace trimmed by design)'
         else 'PASS'
       end as type_verdict,
       l.transform
  from lineage l
  left join raw_cols r
         on r.table_catalog = l.raw_db and r.table_schema = l.raw_schema
        and r.table_name = l.raw_table and r.column_name = l.raw_column
  left join sat_cols s on s.column_name = l.sat_column
 order by l.sat_column, l.raw_table, l.raw_column;

-- SQL query (b) -- value format on the sample (1:1 mapped columns; run the ALTER SESSION first)
alter session set TIMESTAMP_NTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9',
                  TIMESTAMP_LTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  TIMESTAMP_TZ_OUTPUT_FORMAT  = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  DATE_OUTPUT_FORMAT          = 'YYYY-MM-DD';

with sat_rows as (
    -- this project's rows of the satellite
    select s.CLAIM_PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'PARTY_ROLE_TYPE', to_varchar(s."PARTY_ROLE_TYPE"),
               'ROLE_SEQUENCE', to_varchar(s."ROLE_SEQUENCE")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_CLAIM_PARTY_ROLE s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
raw_vals as (
    -- 1. CLM_INTERESTED_PARTIES
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('LNK_CLAIM_PARTY|' || nullif(trim("PART_ID"::varchar), '') || '|' || nullif(trim("CLAIM_ID"::varchar), '')) AS VARCHAR))), '')) as hkey,
           'OPUS_CLM_INTERESTED_PARTIES' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.CLM_INTERESTED_PARTIES,
           lateral flatten(input => object_construct_keep_null(
                                     'PARTY_ROLE_TYPE', array_construct(to_varchar("IP_TYPE"), typeof(to_variant("IP_TYPE"))),
                                     'ROLE_SEQUENCE', array_construct(to_varchar("IP_NO"), typeof(to_variant("IP_NO")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
),
classified as (
    select v.hkey, v.rs, v.col,
           case
             when equal_null(v.val, r.raw_value) then 0                                                  -- EXACT
             when v.val is null and nullif(trim(r.raw_value), '') is null then 1                         -- BLANK -> NULL (by design)
             when v.val = trim(r.raw_value) then 1                                                       -- WHITESPACE TRIMMED (by design)
             when r.raw_type <> 'VARCHAR' and v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 2             -- TYPED VALUE KEPT, TEXT FORM DIFFERS
             when r.raw_type <> 'VARCHAR' and try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 2
             when v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 3             -- DATE/TIME RE-FORMATTED
             when try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 3             -- NUMBER RE-FORMATTED
             when try_to_decimal(r.raw_value, 38, 12) <> round(try_to_decimal(r.raw_value, 38, 12), 0)
                  and try_to_decimal(v.val, 38, 12) = round(try_to_decimal(r.raw_value, 38, 12), 0) then 4  -- DECIMALS LOST
             when startswith(r.raw_value, v.val) then 5                                                  -- TRUNCATED
             else 6                                                                            -- DIFFERENT VALUE
           end as cls
      from sat_cols v
      join raw_vals r on r.hkey = v.hkey and r.rs_key = v.rs_key and r.col = v.col
),
best as (
    -- a key can have several RAW rows: keep the closest one per (unit, column)
    select hkey, rs, col, min(cls) as cls from classified group by hkey, rs, col
)
select 'OPUS' as project, 'SAT_LNK_CLAIM_PARTY_ROLE' as satellite, col as sat_column,
       count(*)              as compared,
       count_if(cls = 0)     as exact,
       count_if(cls = 1)     as trimmed_or_blank_to_null,
       count_if(cls = 2)     as typed_value_kept_text_differs,
       count_if(cls = 3)     as reformatted,
       count_if(cls = 4)     as decimals_lost,
       count_if(cls = 5)     as truncated,
       count_if(cls = 6)     as different_value,
       case when count_if(cls in (3, 4, 5)) > 0 then 'FAIL'
            when count_if(cls = 6) > 0 then 'REVIEW (value differs - see DM-A2)'
            when count_if(cls = 1) > 0 then 'PASS (whitespace / blank->null by design)'
            else 'PASS' end  as format_status
  from best
 group by col
 order by col;



