        ('RELATIONSHIP_TO_INSURED', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CTNGY_GC_MEM_DATA', 'RELATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("RELATION"::varchar), '''')'),
        ('APPOINTEE_NAME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CTNGY_PA_MEM_DTLS', 'ASSIGNEE_NAME', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("ASSIGNEE_NAME"::varchar), '''')'),
