        ('APPOINTEE_NAME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_EC_MEM_DTLS_EXTN', 'ASSIGNEE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("ASSIGNEE"::varchar), '''')'),
