        ('RELATIONSHIP_TO_INSURED', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HLT_ENSURE_MEM_DTLS', 'RELATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("RELATION"::varchar), '''')'),
        ('APPOINTEE_NAME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HM_MEMBER_DTLS', 'ASSIGNEE_NAME', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("ASSIGNEE_NAME"::varchar), '''')'),
        ('RELATIONSHIP_TO_INSURED', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HM_MEMBER_DTLS', 'RELATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("RELATION"::varchar), '''')'),
        ('APPOINTEE_NAME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_PA_DETL_EXTN', 'ASSIGNEE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("ASSIGNEE"::varchar), '''')'),
        ('RELATIONSHIP_TO_INSURED', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_PA_DETL_EXTN', 'RELATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("RELATION"::varchar), '''')'),
        ('APPOINTEE_NAME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SH_MEM_DTLS_EXTN', 'ASSIGNEE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("ASSIGNEE"::varchar), '''')'),
        ('RELATIONSHIP_TO_INSURED', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SH_MEM_DTLS_EXTN', 'RELATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("RELATION"::varchar), '''')'),
        ('APPOINTEE_NAME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SPP_MEMBER_DTLS', 'ASSIGNEE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("ASSIGNEE"::varchar), '''')'),
