    select * from values
        ('BODYMASSINDEX', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HCF_MEMBER_DTLS', 'OBESITY_FLAG', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("OBESITY_FLAG"::varchar), ''''))), '''')'),
        ('BODYMASSINDEX', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SPP_MEMBER_DTLS', 'OBESITY', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("OBESITY"::varchar), ''''))), '''')'),
        ('HEIGHT', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_EC_MEM_DTLS_EXTN', 'HEIGHT_CM', 'TRIM, BLANK->NULL, SCALE0, SAT_VARCHAR', 'nullif(trim(to_varchar(("HEIGHT_CM"::number))), '''')'),
        ('HEIGHT', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HCF_MEMBER_DTLS', 'HEIGHT_FLAG', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("HEIGHT_FLAG"::varchar), ''''))), '''')'),
        ('MATERNITYSTATUS', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_EC_MEM_DTLS_EXTN', 'PREGNANT_YN', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("PREGNANT_YN"::varchar), ''''))), '''')'),
        ('SMOKERINDICATOR', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_EC_MEM_DTLS_EXTN', 'SMOKER_YN', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("SMOKER_YN"::varchar), ''''))), '''')'),
        ('SMOKERINDICATOR', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HCF_MEMBER_DTLS', 'SMOKER_FLAG', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("SMOKER_FLAG"::varchar), ''''))), '''')'),
        ('SMOKERINDICATOR', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SH_MEM_DTLS_EXTN', 'SMOKER_YN', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("SMOKER_YN"::varchar), ''''))), '''')'),
        ('WEIGHT', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_EC_MEM_DTLS_EXTN', 'WEIGHT_KG', 'TRIM, BLANK->NULL, SCALE0, SAT_VARCHAR', 'nullif(trim(to_varchar(("WEIGHT_KG"::number))), '''')'),
        ('WEIGHT', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HCF_MEMBER_DTLS', 'WEIGHT_FLAG', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("WEIGHT_FLAG"::varchar), ''''))), '''')'),
        ('WEIGHT', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SPP_MEMBER_DTLS', 'WEIGHT', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("WEIGHT"::varchar), ''''))), '''')')
),
raw_cols as (
    select table_catalog, table_schema, table_name, column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'UTILS'
       and table_name in ('BJAZ_EC_MEM_DTLS_EXTN', 'BJAZ_HCF_MEMBER_DTLS', 'BJAZ_SH_MEM_DTLS_EXTN', 'BJAZ_SPP_MEMBER_DTLS')
),
sat_cols as (
    select column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'BGIL_DATA_MODEL'
       and table_name = 'SAT_PARTY_HEALTH_PROFILE'
)
select 'OPUS' as project, 'SAT_PARTY_HEALTH_PROFILE' as satellite,
       l.sat_column, case when s.data_type = 'TEXT' then 'TEXT(' || s.char_len || ')' when s.data_type = 'NUMBER' then 'NUMBER(' || s.num_prec || ',' || s.num_scale || ')' when s.data_type like 'TIMESTAMP%' then s.data_type || '(' || s.dt_prec || ')' else s.data_type end as sat_type,
       l.raw_table, l.raw_column, case when r.data_type = 'TEXT' then 'TEXT(' || r.char_len || ')' when r.data_type = 'NUMBER' then 'NUMBER(' || r.num_prec || ',' || r.num_scale || ')' when r.data_type like 'TIMESTAMP%' then r.data_type || '(' || r.dt_prec || ')' else r.data_type end as raw_type,
       l.transform_flags,
       case
         when r.data_type is null then 'FAIL - RAW COLUMN NOT FOUND'
         when s.data_type is null then 'FAIL - SAT COLUMN NOT FOUND'
         when r.data_type = 'NUMBER' and r.num_scale > 0 and l.transform_flags like '%SCALE0%'
              then 'FAIL - DECIMALS LOST (cast to integer NUMBER on load)'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER' and s.num_scale < r.num_scale then 'FAIL - DECIMALS LOST'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER'
              and s.num_prec - s.num_scale < r.num_prec - r.num_scale then 'FAIL - PRECISION RISK'
         when r.data_type = 'TEXT' and s.data_type = 'TEXT' and s.char_len < r.char_len then 'FAIL - TRUNCATION RISK (length)'
         when r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%' and s.dt_prec < r.dt_prec
              then 'FAIL - FRACTIONAL SECONDS TRUNCATED'
         when r.data_type = 'DATE' and s.data_type like 'TIMESTAMP%' then 'REVIEW - DATE LOADED AS TIMESTAMP'
         when r.data_type <> 'TEXT' and s.data_type = 'TEXT' then 'REVIEW - STORED AS TEXT (see query b)'
         when r.data_type = 'TEXT' and s.data_type <> 'TEXT' then 'REVIEW - TEXT CONVERTED TO ' || s.data_type
         when r.data_type <> s.data_type and not (r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%')
              then 'REVIEW - TYPE CHANGED'
         when l.transform_flags like '%TRIM%' then 'PASS (whitespace trimmed by design)'
         else 'PASS'
       end as type_verdict,
       l.transform
  from lineage l
  left join raw_cols r
         on r.table_catalog = l.raw_db and r.table_schema = l.raw_schema
        and r.table_name = l.raw_table and r.column_name = l.raw_column
  left join sat_cols s on s.column_name = l.sat_column
 order by l.sat_column, l.raw_table, l.raw_column;

-- SQL query (b) -- value format on the sample (1:1 mapped columns; run the ALTER SESSION first)
alter session set TIMESTAMP_NTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9',
                  TIMESTAMP_LTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  TIMESTAMP_TZ_OUTPUT_FORMAT  = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  DATE_OUTPUT_FORMAT          = 'YYYY-MM-DD';

with sat_rows as (
    -- this project's rows of the satellite
    select s.PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, iff(s.RECORD_SOURCE in ('OPUS_BJAZ_M_KYC_DRIVING_LICENCE', 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS'), s.RECORD_SOURCE, 'STITCH') as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'HEIGHT', to_varchar(s."HEIGHT"),
               'MATERNITYSTATUS', to_varchar(s."MATERNITYSTATUS"),
               'SMOKERINDICATOR', to_varchar(s."SMOKERINDICATOR"),
               'WEIGHT', to_varchar(s."WEIGHT"),
               'BODYMASSINDEX', to_varchar(s."BODYMASSINDEX")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_HEALTH_PROFILE s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
raw_vals as (
    -- 1. BJAZ_EC_MEM_DTLS_EXTN (stitch stitch_party_health_profile t0)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'HEIGHT', array_construct(to_varchar("HEIGHT_CM"), typeof(to_variant("HEIGHT_CM"))),
                                     'MATERNITYSTATUS', array_construct(to_varchar("PREGNANT_YN"), typeof(to_variant("PREGNANT_YN"))),
                                     'SMOKERINDICATOR', array_construct(to_varchar("SMOKER_YN"), typeof(to_variant("SMOKER_YN"))),
                                     'WEIGHT', array_construct(to_varchar("WEIGHT_KG"), typeof(to_variant("WEIGHT_KG")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_HCF_MEMBER_DTLS (stitch stitch_party_health_profile t1)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'BODYMASSINDEX', array_construct(to_varchar("OBESITY_FLAG"), typeof(to_variant("OBESITY_FLAG"))),
                                     'HEIGHT', array_construct(to_varchar("HEIGHT_FLAG"), typeof(to_variant("HEIGHT_FLAG"))),
                                     'SMOKERINDICATOR', array_construct(to_varchar("SMOKER_FLAG"), typeof(to_variant("SMOKER_FLAG"))),
                                     'WEIGHT', array_construct(to_varchar("WEIGHT_FLAG"), typeof(to_variant("WEIGHT_FLAG")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BJAZ_SH_MEM_DTLS_EXTN (stitch stitch_party_health_profile t2)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'SMOKERINDICATOR', array_construct(to_varchar("SMOKER_YN"), typeof(to_variant("SMOKER_YN")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 4. BJAZ_SPP_MEMBER_DTLS (stitch stitch_party_health_profile t3)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'BODYMASSINDEX', array_construct(to_varchar("OBESITY"), typeof(to_variant("OBESITY"))),
                                     'WEIGHT', array_construct(to_varchar("WEIGHT"), typeof(to_variant("WEIGHT")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
),
classified as (
    select v.hkey, v.rs, v.col,
           case
             when equal_null(v.val, r.raw_value) then 0                                                  -- EXACT
             when v.val is null and nullif(trim(r.raw_value), '') is null then 1                         -- BLANK -> NULL (by design)
             when v.val = trim(r.raw_value) then 1                                                       -- WHITESPACE TRIMMED (by design)
             when r.raw_type <> 'VARCHAR' and v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 2             -- TYPED VALUE KEPT, TEXT FORM DIFFERS
             when r.raw_type <> 'VARCHAR' and try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 2
             when v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 3             -- DATE/TIME RE-FORMATTED
             when try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 3             -- NUMBER RE-FORMATTED
             when try_to_decimal(r.raw_value, 38, 12) <> round(try_to_decimal(r.raw_value, 38, 12), 0)
                  and try_to_decimal(v.val, 38, 12) = round(try_to_decimal(r.raw_value, 38, 12), 0) then 4  -- DECIMALS LOST
             when startswith(r.raw_value, v.val) then 5                                                  -- TRUNCATED
             else 6                                                                            -- DIFFERENT VALUE
           end as cls
      from sat_cols v
      join raw_vals r on r.hkey = v.hkey and r.rs_key = v.rs_key and r.col = v.col
),
best as (
    -- a key can have several RAW rows: keep the closest one per (unit, column)
    select hkey, rs, col, min(cls) as cls from classified group by hkey, rs, col
)
select 'OPUS' as project, 'SAT_PARTY_HEALTH_PROFILE' as satellite, col as sat_column,
       count(*)              as compared,
       count_if(cls = 0)     as exact,
       count_if(cls = 1)     as trimmed_or_blank_to_null,
       count_if(cls = 2)     as typed_value_kept_text_differs,
       count_if(cls = 3)     as reformatted,
       count_if(cls = 4)     as decimals_lost,
       count_if(cls = 5)     as truncated,
       count_if(cls = 6)     as different_value,
       case when count_if(cls in (3, 4, 5)) > 0 then 'FAIL'
            when count_if(cls = 6) > 0 then 'REVIEW (value differs - see DM-A2)'
            when count_if(cls = 1) > 0 then 'PASS (whitespace / blank->null by design)'
            else 'PASS' end  as format_status
  from best
 group by col
 order by col;



----------------------------------------------------------------------------------------
-- 125. OPUS — SAT_PARTY_IDENTIFICATION   [Implemented]
-- 12 mapped column(s), 28 RAW column lineage row(s); 12 column(s) are 1:1 and
-- value-checked in (b). Static transform flags -- integer cast on load (decimals lost if
-- the RAW column has a scale): IDENTIFICATIONNUMBER<-MEMBER_REF_NUMBER. 19 RAW
-- branch(es): AZBJ_PARTNER_EXTN, BJAZ_CLM_SUPP_EXTN, BJAZ_CTNGY_FF_DTLS_EXTN,
-- BJAZ_CTNGY_PA_MEM_DTLS, BJAZ_EC_MEM_DTLS_EXTN, BJAZ_HCF_MEMBER_DTLS,
-- BJAZ_HLT_ENSURE_MEM_DTLS, BJAZ_HM_HOSPITAL_MASTER, BJAZ_INTERMEDIARY,
-- BJAZ_STARPKG_FF_DTLS, CP_PARTNERS, BJAZ_M_KYC_DRIVING_LICENCE, BJAZ_M_KYC_GSTN,
-- BJAZ_M_KYC_PAN, BJAZ_M_KYC_PASSPORT, BJAZ_M_KYC_VOTER, BJAZ_T_CKYC_OTP,
-- BJAZ_T_KYC_INCOMING, BJAZ_T_KYC_NAME_MATCH. Not mapped by this project (always NULL):
-- CKYCNUMBER.
----------------------------------------------------------------------------------------
-- SQL query (a) -- column type / length / precision / scale: RAW vs satellite
with lineage (sat_column, raw_db, raw_schema, raw_table, raw_column, transform_flags, transform) as (
    -- generated from the dbt models: every RAW column that feeds a satellite column
    select * from values
        ('EIANUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'AZBJ_PARTNER_EXTN', 'EIA_NO', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("EIA_NO"::varchar), '''')'),
        ('IDENTIFICATIONNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'AZBJ_PARTNER_EXTN', 'UNIQUE_ID', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("UNIQUE_ID"::varchar), '''')'),
        ('GSTTAXPAYERTYPE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CLM_SUPP_EXTN', 'TAXPAYER_TYPE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("TAXPAYER_TYPE"::varchar), '''')'),
        ('PANNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CLM_SUPP_EXTN', 'PAN_NO', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PAN_NO"::varchar), '''')'),
        ('TANNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CLM_SUPP_EXTN', 'TAN_NUMBER', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("TAN_NUMBER"::varchar), '''')'),
        ('PASSPORTNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CTNGY_FF_DTLS_EXTN', 'PASSPORTNO', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PASSPORTNO"::varchar), '''')'),
        ('AADHAARNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CTNGY_PA_MEM_DTLS', 'AADHAR_CARD_NO', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("AADHAR_CARD_NO"::varchar), '''')'),
        ('EIANUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CTNGY_PA_MEM_DTLS', 'EIA_NO', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("EIA_NO"::varchar), '''')'),
        ('IDENTIFICATIONNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CTNGY_PA_MEM_DTLS', 'MEMBER_REF_NUMBER', 'SCALE0, SAT_VARCHAR', '("MEMBER_REF_NUMBER"::number)'),
        ('PANNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CTNGY_PA_MEM_DTLS', 'PAN_CARD_NO', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PAN_CARD_NO"::varchar), '''')'),
        ('PASSPORTNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CTNGY_PA_MEM_DTLS', 'PASSPORT_NUMBER', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PASSPORT_NUMBER"::varchar), '''')'),
        ('AGEPROOFTYPE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_EC_MEM_DTLS_EXTN', 'AGE_PROOF', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("AGE_PROOF"::varchar), '''')'),
        ('AGEPROOFTYPE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HCF_MEMBER_DTLS', 'AGE_PROOF_FLAG', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("AGE_PROOF_FLAG"::varchar), '''')'),
        ('AGEPROOFTYPE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HLT_ENSURE_MEM_DTLS', 'AGE_PROOF_YN', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("AGE_PROOF_YN"::varchar), '''')'),
        ('IDENTIFICATIONNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HM_HOSPITAL_MASTER', 'HOSPITAL_NO', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("HOSPITAL_NO"::varchar), '''')'),
        ('GSTIN', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_INTERMEDIARY', 'GST_NO', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("GST_NO"::varchar), '''')'),
        ('GSTREGISTRATIONSTATUS', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_INTERMEDIARY', 'GST_STATUS', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("GST_STATUS"::varchar), '''')'),
        ('PANNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_INTERMEDIARY', 'PAN_NUMBER', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PAN_NUMBER"::varchar), '''')'),
        ('PASSPORTNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_STARPKG_FF_DTLS', 'PASSPORTNO', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PASSPORTNO"::varchar), '''')'),
        ('IDENTIFICATIONNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'CP_PARTNERS', 'TAX_ID', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("TAX_ID"::varchar), '''')'),
        ('VATREGISTRATIONNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'CP_PARTNERS', 'VAT_NUMBER', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("VAT_NUMBER"::varchar), '''')'),
        ('GSTIN', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_M_KYC_GSTN', 'GSTIN_NUMBER', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("GSTIN_NUMBER"::varchar), '''')'),
        ('PANNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_M_KYC_PAN', 'PAN_NUMBER', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PAN_NUMBER"::varchar), '''')'),
        ('PASSPORTNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_M_KYC_PASSPORT', 'PASSPORT_NUMBER', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PASSPORT_NUMBER"::varchar), '''')'),
        ('VOTERIDNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_M_KYC_VOTER', 'VOTER_NUMBER', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("VOTER_NUMBER"::varchar), '''')'),
        ('IDENTIFICATIONNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_CKYC_OTP', 'INPUT', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("INPUT"::varchar), '''')'),
        ('IDENTIFICATIONNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_INCOMING', 'SEARCH_INPUT', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("SEARCH_INPUT"::varchar), '''')'),
        ('IDENTIFICATIONNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_NAME_MATCH', 'INPUT', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("INPUT"::varchar), '''')')
),
raw_cols as (
    select table_catalog, table_schema, table_name, column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'UTILS'
       and table_name in ('AZBJ_PARTNER_EXTN', 'BJAZ_CLM_SUPP_EXTN', 'BJAZ_CTNGY_FF_DTLS_EXTN', 'BJAZ_CTNGY_PA_MEM_DTLS', 'BJAZ_EC_MEM_DTLS_EXTN', 'BJAZ_HCF_MEMBER_DTLS', 'BJAZ_HLT_ENSURE_MEM_DTLS', 'BJAZ_HM_HOSPITAL_MASTER', 'BJAZ_INTERMEDIARY', 'BJAZ_M_KYC_GSTN', 'BJAZ_M_KYC_PAN', 'BJAZ_M_KYC_PASSPORT', 'BJAZ_M_KYC_VOTER', 'BJAZ_STARPKG_FF_DTLS', 'BJAZ_T_CKYC_OTP', 'BJAZ_T_KYC_INCOMING', 'BJAZ_T_KYC_NAME_MATCH', 'CP_PARTNERS')
),
sat_cols as (
    select column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'BGIL_DATA_MODEL'
       and table_name = 'SAT_PARTY_IDENTIFICATION'
)
select 'OPUS' as project, 'SAT_PARTY_IDENTIFICATION' as satellite,
       l.sat_column, case when s.data_type = 'TEXT' then 'TEXT(' || s.char_len || ')' when s.data_type = 'NUMBER' then 'NUMBER(' || s.num_prec || ',' || s.num_scale || ')' when s.data_type like 'TIMESTAMP%' then s.data_type || '(' || s.dt_prec || ')' else s.data_type end as sat_type,
       l.raw_table, l.raw_column, case when r.data_type = 'TEXT' then 'TEXT(' || r.char_len || ')' when r.data_type = 'NUMBER' then 'NUMBER(' || r.num_prec || ',' || r.num_scale || ')' when r.data_type like 'TIMESTAMP%' then r.data_type || '(' || r.dt_prec || ')' else r.data_type end as raw_type,
       l.transform_flags,
       case
         when r.data_type is null then 'FAIL - RAW COLUMN NOT FOUND'
         when s.data_type is null then 'FAIL - SAT COLUMN NOT FOUND'
         when r.data_type = 'NUMBER' and r.num_scale > 0 and l.transform_flags like '%SCALE0%'
              then 'FAIL - DECIMALS LOST (cast to integer NUMBER on load)'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER' and s.num_scale < r.num_scale then 'FAIL - DECIMALS LOST'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER'
              and s.num_prec - s.num_scale < r.num_prec - r.num_scale then 'FAIL - PRECISION RISK'
         when r.data_type = 'TEXT' and s.data_type = 'TEXT' and s.char_len < r.char_len then 'FAIL - TRUNCATION RISK (length)'
         when r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%' and s.dt_prec < r.dt_prec
              then 'FAIL - FRACTIONAL SECONDS TRUNCATED'
         when r.data_type = 'DATE' and s.data_type like 'TIMESTAMP%' then 'REVIEW - DATE LOADED AS TIMESTAMP'
         when r.data_type <> 'TEXT' and s.data_type = 'TEXT' then 'REVIEW - STORED AS TEXT (see query b)'
         when r.data_type = 'TEXT' and s.data_type <> 'TEXT' then 'REVIEW - TEXT CONVERTED TO ' || s.data_type
         when r.data_type <> s.data_type and not (r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%')
              then 'REVIEW - TYPE CHANGED'
         when l.transform_flags like '%TRIM%' then 'PASS (whitespace trimmed by design)'
         else 'PASS'
       end as type_verdict,
       l.transform
  from lineage l
  left join raw_cols r
         on r.table_catalog = l.raw_db and r.table_schema = l.raw_schema
        and r.table_name = l.raw_table and r.column_name = l.raw_column
  left join sat_cols s on s.column_name = l.sat_column
 order by l.sat_column, l.raw_table, l.raw_column;

-- SQL query (b) -- value format on the sample (1:1 mapped columns; run the ALTER SESSION first)
alter session set TIMESTAMP_NTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9',
                  TIMESTAMP_LTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  TIMESTAMP_TZ_OUTPUT_FORMAT  = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  DATE_OUTPUT_FORMAT          = 'YYYY-MM-DD';

with sat_rows as (
    -- this project's rows of the satellite
    select s.PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'EIANUMBER', to_varchar(s."EIANUMBER"),
               'IDENTIFICATIONNUMBER', to_varchar(s."IDENTIFICATIONNUMBER"),
               'GSTTAXPAYERTYPE', to_varchar(s."GSTTAXPAYERTYPE"),
               'PANNUMBER', to_varchar(s."PANNUMBER"),
               'TANNUMBER', to_varchar(s."TANNUMBER"),
               'PASSPORTNUMBER', to_varchar(s."PASSPORTNUMBER"),
               'AADHAARNUMBER', to_varchar(s."AADHAARNUMBER"),
               'AGEPROOFTYPE', to_varchar(s."AGEPROOFTYPE"),
               'GSTIN', to_varchar(s."GSTIN"),
               'GSTREGISTRATIONSTATUS', to_varchar(s."GSTREGISTRATIONSTATUS"),
               'VATREGISTRATIONNUMBER', to_varchar(s."VATREGISTRATIONNUMBER"),
               'VOTERIDNUMBER', to_varchar(s."VOTERIDNUMBER")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTIFICATION s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
raw_vals as (
    -- 1. AZBJ_PARTNER_EXTN
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'EIANUMBER', array_construct(to_varchar("EIA_NO"), typeof(to_variant("EIA_NO"))),
                                     'IDENTIFICATIONNUMBER', array_construct(to_varchar("UNIQUE_ID"), typeof(to_variant("UNIQUE_ID")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_CLM_SUPP_EXTN
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'GSTTAXPAYERTYPE', array_construct(to_varchar("TAXPAYER_TYPE"), typeof(to_variant("TAXPAYER_TYPE"))),
                                     'PANNUMBER', array_construct(to_varchar("PAN_NO"), typeof(to_variant("PAN_NO"))),
                                     'TANNUMBER', array_construct(to_varchar("TAN_NUMBER"), typeof(to_variant("TAN_NUMBER")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BJAZ_CTNGY_FF_DTLS_EXTN
    select * from (
