    -- 11. CP_PARTNERS
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.CP_PARTNERS,
           lateral flatten(input => object_construct_keep_null(
                                     'IDENTIFICATIONNUMBER', array_construct(to_varchar("TAX_ID"), typeof(to_variant("TAX_ID"))),
                                     'VATREGISTRATIONNUMBER', array_construct(to_varchar("VAT_NUMBER"), typeof(to_variant("VAT_NUMBER")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 12. BJAZ_M_KYC_GSTN
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif('GSTIN:' || upper(trim(coalesce(nullif(trim("GSTIN_NUMBER"::varchar), ''),''))), 'GSTIN:'))) AS VARCHAR))), '')) as hkey,
           'OPUS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_GSTN,
           lateral flatten(input => object_construct_keep_null(
                                     'GSTIN', array_construct(to_varchar("GSTIN_NUMBER"), typeof(to_variant("GSTIN_NUMBER")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 13. BJAZ_M_KYC_PAN
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif('PAN:' || upper(trim(coalesce(nullif(trim("PAN_NUMBER"::varchar), ''),''))), 'PAN:'))) AS VARCHAR))), '')) as hkey,
           'OPUS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_PAN,
           lateral flatten(input => object_construct_keep_null(
                                     'PANNUMBER', array_construct(to_varchar("PAN_NUMBER"), typeof(to_variant("PAN_NUMBER")))
                                 )) f
