        ('DATEOFBIRTH', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_OCR', 'DOB', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("DOB"::varchar), '''')'),
        ('GENDERCODE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_OCR', 'GENDER', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("GENDER"::varchar), '''')'),
