                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 6. BJAZ_CTNGY_PA_MEM_DTLS (stitch stitch_party_identity t7)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'AGE', array_construct(to_varchar("AGE"), typeof(to_variant("AGE"))),
                                     'DATEOFBIRTH', array_construct(to_varchar("DOB"), typeof(to_variant("DOB"))),
                                     'GENDERCODE', array_construct(to_varchar("GENDER"), typeof(to_variant("GENDER"))),
