classified as (
    select v.hkey, v.rs, v.col,
           case
             when equal_null(v.val, r.raw_value) then 0                                                  -- EXACT
             when v.val is null and nullif(trim(r.raw_value), '') is null then 1                         -- BLANK -> NULL (by design)
             when v.val = trim(r.raw_value) then 1                                                       -- WHITESPACE TRIMMED (by design)
             when r.raw_type <> 'VARCHAR' and v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 2             -- TYPED VALUE KEPT, TEXT FORM DIFFERS
             when r.raw_type <> 'VARCHAR' and try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 2
             when v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 3             -- DATE/TIME RE-FORMATTED
             when try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 3             -- NUMBER RE-FORMATTED
             when try_to_decimal(r.raw_value, 38, 12) <> round(try_to_decimal(r.raw_value, 38, 12), 0)
                  and try_to_decimal(v.val, 38, 12) = round(try_to_decimal(r.raw_value, 38, 12), 0) then 4  -- DECIMALS LOST
             when startswith(r.raw_value, v.val) then 5                                                  -- TRUNCATED
             else 6                                                                            -- DIFFERENT VALUE
           end as cls
      from sat_cols v
      join raw_vals r on r.hkey = v.hkey and r.rs_key = v.rs_key and r.col = v.col
),
best as (
    -- a key can have several RAW rows: keep the closest one per (unit, column)
    select hkey, rs, col, min(cls) as cls from classified group by hkey, rs, col
)
select 'OPUS' as project, 'SAT_PARTY_IDENTITY' as satellite, col as sat_column,
       count(*)              as compared,
       count_if(cls = 0)     as exact,
       count_if(cls = 1)     as trimmed_or_blank_to_null,
       count_if(cls = 2)     as typed_value_kept_text_differs,
       count_if(cls = 3)     as reformatted,
       count_if(cls = 4)     as decimals_lost,
       count_if(cls = 5)     as truncated,
       count_if(cls = 6)     as different_value,
       case when count_if(cls in (3, 4, 5)) > 0 then 'FAIL'
            when count_if(cls = 6) > 0 then 'REVIEW (value differs - see DM-A2)'
            when count_if(cls = 1) > 0 then 'PASS (whitespace / blank->null by design)'
            else 'PASS' end  as format_status
  from best
 group by col
 order by col;



----------------------------------------------------------------------------------------
-- 127. OPUS — SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS   [Implemented]
-- 10 mapped column(s), 23 RAW column lineage row(s); 10 column(s) are 1:1 and
-- value-checked in (b). Static transform flags -- integer cast on load (decimals lost if
-- the RAW column has a scale): ANNUALINCOME<-GROSS_INCOME, ANNUALINCOME<-MONTHLY_INCOME,
-- NUMBEROFCHILDREN<-NO_OF_CHILDREN. 3 RAW branch(es): stitch
-- stitch_party_individual_demographics, BJAZ_T_CKYC_PERSONAL_DTLS, BJAZ_T_KYC_OCR.
-- stitch_party_individual_demographics reproduced from 8 RAW tables with no watermark
-- window; every row combination per key is kept because the stitch keeps one of them
-- arbitrarily.
----------------------------------------------------------------------------------------
-- SQL query (a) -- column type / length / precision / scale: RAW vs satellite
with lineage (sat_column, raw_db, raw_schema, raw_table, raw_column, transform_flags, transform) as (
    -- generated from the dbt models: every RAW column that feeds a satellite column
    select * from values
        ('ANNUALHOUSEHOLDINCOME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'AZBJ_PARTNER_EXTN', 'FAMILY_MONTHLY_INCOME', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("FAMILY_MONTHLY_INCOME"::varchar), ''''))), '''')'),
        ('ANNUALINCOME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_EC_MEM_DTLS_EXTN', 'GROSS_INCOME', 'TRIM, BLANK->NULL, SCALE0, SAT_VARCHAR', 'nullif(trim(to_varchar(("GROSS_INCOME"::number))), '''')'),
        ('ANNUALINCOME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HCF_MEMBER_DTLS', 'MONTHLY_INCOME', 'TRIM, BLANK->NULL, SCALE0, SAT_VARCHAR', 'nullif(trim(to_varchar(("MONTHLY_INCOME"::number))), '''')'),
        ('ANNUALINCOME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HM_MEMBER_DTLS', 'GROSS_INCOME', 'TRIM, BLANK->NULL, SCALE0, SAT_VARCHAR', 'nullif(trim(to_varchar(("GROSS_INCOME"::number))), '''')'),
        ('ANNUALINCOME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SH_MEM_DTLS_EXTN', 'GROSS_INCOME', 'TRIM, BLANK->NULL, SCALE0, SAT_VARCHAR', 'nullif(trim(to_varchar(("GROSS_INCOME"::number))), '''')'),
        ('DESIGNATION', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HM_MEMBER_DTLS', 'DESIGNATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("DESIGNATION"::varchar), ''''))), '''')'),
        ('EDUCATIONALQUALIFICATION', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'AZBJ_PARTNER_EXTN', 'EDUCATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("EDUCATION"::varchar), ''''))), '''')'),
        ('FATHERNAME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'AZBJ_PARTNER_EXTN', 'FATHER_NAME', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("FATHER_NAME"::varchar), ''''))), '''')'),
        ('MARITALSTATUS', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'CP_PARTNERS', 'MARITAL_STATUS', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("MARITAL_STATUS"::varchar), ''''))), '''')'),
        ('NUMBEROFCHILDREN', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'AZBJ_PARTNER_EXTN', 'NO_OF_CHILDREN', 'TRIM, BLANK->NULL, SCALE0, SAT_VARCHAR', 'nullif(trim(to_varchar(("NO_OF_CHILDREN"::number))), '''')'),
        ('OCCUPATIONCODE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_EC_MEM_DTLS_EXTN', 'OCCUPATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("OCCUPATION"::varchar), ''''))), '''')'),
        ('OCCUPATIONCODE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HCF_MEMBER_DTLS', 'MEMBER_OCCUPATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("MEMBER_OCCUPATION"::varchar), ''''))), '''')'),
        ('OCCUPATIONCODE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HC_PART_EXTN', 'OCCUPATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("OCCUPATION"::varchar), ''''))), '''')'),
        ('OCCUPATIONCODE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HM_MEMBER_DTLS', 'OCCUPATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("OCCUPATION"::varchar), ''''))), '''')'),
        ('OCCUPATIONCODE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SH_MEM_DTLS_EXTN', 'OCCUPATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("OCCUPATION"::varchar), ''''))), '''')'),
        ('OCCUPATIONCODE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SPP_MEMBER_DTLS', 'MEMBER_OCCUPATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("MEMBER_OCCUPATION"::varchar), ''''))), '''')'),
        ('OCCUPATIONCODE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'CP_PARTNERS', 'OCCUPATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("OCCUPATION"::varchar), ''''))), '''')'),
        ('OCCUPATIONDESCRIPTION', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'AZBJ_PARTNER_EXTN', 'OCCUPATION_DESC_GEN', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("OCCUPATION_DESC_GEN"::varchar), ''''))), '''')'),
        ('SPOUSENAME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'AZBJ_PARTNER_EXTN', 'SPOUSE_NAME', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim(to_varchar(nullif(trim("SPOUSE_NAME"::varchar), ''''))), '''')'),
        ('FATHERNAME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_CKYC_PERSONAL_DTLS', 'FATHER_FULLNAME', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("FATHER_FULLNAME"::varchar), '''')'),
        ('MARITALSTATUS', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_CKYC_PERSONAL_DTLS', 'MARITAL_STATUS', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("MARITAL_STATUS"::varchar), '''')'),
        ('OCCUPATIONCODE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_CKYC_PERSONAL_DTLS', 'OCCUPATION', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("OCCUPATION"::varchar), '''')'),
        ('FATHERNAME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_OCR', 'FATHER', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("FATHER"::varchar), '''')')
),
raw_cols as (
    select table_catalog, table_schema, table_name, column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'UTILS'
       and table_name in ('AZBJ_PARTNER_EXTN', 'BJAZ_EC_MEM_DTLS_EXTN', 'BJAZ_HCF_MEMBER_DTLS', 'BJAZ_HC_PART_EXTN', 'BJAZ_HM_MEMBER_DTLS', 'BJAZ_SH_MEM_DTLS_EXTN', 'BJAZ_SPP_MEMBER_DTLS', 'BJAZ_T_CKYC_PERSONAL_DTLS', 'BJAZ_T_KYC_OCR', 'CP_PARTNERS')
),
sat_cols as (
    select column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'BGIL_DATA_MODEL'
       and table_name = 'SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS'
)
select 'OPUS' as project, 'SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS' as satellite,
       l.sat_column, case when s.data_type = 'TEXT' then 'TEXT(' || s.char_len || ')' when s.data_type = 'NUMBER' then 'NUMBER(' || s.num_prec || ',' || s.num_scale || ')' when s.data_type like 'TIMESTAMP%' then s.data_type || '(' || s.dt_prec || ')' else s.data_type end as sat_type,
       l.raw_table, l.raw_column, case when r.data_type = 'TEXT' then 'TEXT(' || r.char_len || ')' when r.data_type = 'NUMBER' then 'NUMBER(' || r.num_prec || ',' || r.num_scale || ')' when r.data_type like 'TIMESTAMP%' then r.data_type || '(' || r.dt_prec || ')' else r.data_type end as raw_type,
       l.transform_flags,
       case
         when r.data_type is null then 'FAIL - RAW COLUMN NOT FOUND'
         when s.data_type is null then 'FAIL - SAT COLUMN NOT FOUND'
         when r.data_type = 'NUMBER' and r.num_scale > 0 and l.transform_flags like '%SCALE0%'
              then 'FAIL - DECIMALS LOST (cast to integer NUMBER on load)'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER' and s.num_scale < r.num_scale then 'FAIL - DECIMALS LOST'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER'
              and s.num_prec - s.num_scale < r.num_prec - r.num_scale then 'FAIL - PRECISION RISK'
         when r.data_type = 'TEXT' and s.data_type = 'TEXT' and s.char_len < r.char_len then 'FAIL - TRUNCATION RISK (length)'
         when r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%' and s.dt_prec < r.dt_prec
              then 'FAIL - FRACTIONAL SECONDS TRUNCATED'
         when r.data_type = 'DATE' and s.data_type like 'TIMESTAMP%' then 'REVIEW - DATE LOADED AS TIMESTAMP'
         when r.data_type <> 'TEXT' and s.data_type = 'TEXT' then 'REVIEW - STORED AS TEXT (see query b)'
         when r.data_type = 'TEXT' and s.data_type <> 'TEXT' then 'REVIEW - TEXT CONVERTED TO ' || s.data_type
         when r.data_type <> s.data_type and not (r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%')
              then 'REVIEW - TYPE CHANGED'
         when l.transform_flags like '%TRIM%' then 'PASS (whitespace trimmed by design)'
         else 'PASS'
       end as type_verdict,
       l.transform
  from lineage l
  left join raw_cols r
         on r.table_catalog = l.raw_db and r.table_schema = l.raw_schema
        and r.table_name = l.raw_table and r.column_name = l.raw_column
  left join sat_cols s on s.column_name = l.sat_column
 order by l.sat_column, l.raw_table, l.raw_column;

-- SQL query (b) -- value format on the sample (1:1 mapped columns; run the ALTER SESSION first)
alter session set TIMESTAMP_NTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9',
                  TIMESTAMP_LTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  TIMESTAMP_TZ_OUTPUT_FORMAT  = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  DATE_OUTPUT_FORMAT          = 'YYYY-MM-DD';

with sat_rows as (
    -- this project's rows of the satellite
    select s.PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, iff(s.RECORD_SOURCE in ('OPUS_BJAZ_T_CKYC_PERSONAL_DTLS', 'OPUS_BJAZ_T_KYC_OCR'), s.RECORD_SOURCE, 'STITCH') as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'ANNUALHOUSEHOLDINCOME', to_varchar(s."ANNUALHOUSEHOLDINCOME"),
               'EDUCATIONALQUALIFICATION', to_varchar(s."EDUCATIONALQUALIFICATION"),
               'FATHERNAME', to_varchar(s."FATHERNAME"),
               'NUMBEROFCHILDREN', to_varchar(s."NUMBEROFCHILDREN"),
               'OCCUPATIONDESCRIPTION', to_varchar(s."OCCUPATIONDESCRIPTION"),
               'SPOUSENAME', to_varchar(s."SPOUSENAME"),
               'ANNUALINCOME', to_varchar(s."ANNUALINCOME"),
               'OCCUPATIONCODE', to_varchar(s."OCCUPATIONCODE"),
               'DESIGNATION', to_varchar(s."DESIGNATION"),
               'MARITALSTATUS', to_varchar(s."MARITALSTATUS")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
raw_vals as (
    -- 1. AZBJ_PARTNER_EXTN (stitch stitch_party_individual_demographics t0)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'ANNUALHOUSEHOLDINCOME', array_construct(to_varchar("FAMILY_MONTHLY_INCOME"), typeof(to_variant("FAMILY_MONTHLY_INCOME"))),
                                     'EDUCATIONALQUALIFICATION', array_construct(to_varchar("EDUCATION"), typeof(to_variant("EDUCATION"))),
                                     'FATHERNAME', array_construct(to_varchar("FATHER_NAME"), typeof(to_variant("FATHER_NAME"))),
                                     'NUMBEROFCHILDREN', array_construct(to_varchar("NO_OF_CHILDREN"), typeof(to_variant("NO_OF_CHILDREN"))),
                                     'OCCUPATIONDESCRIPTION', array_construct(to_varchar("OCCUPATION_DESC_GEN"), typeof(to_variant("OCCUPATION_DESC_GEN"))),
                                     'SPOUSENAME', array_construct(to_varchar("SPOUSE_NAME"), typeof(to_variant("SPOUSE_NAME")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_EC_MEM_DTLS_EXTN (stitch stitch_party_individual_demographics t3)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'ANNUALINCOME', array_construct(to_varchar("GROSS_INCOME"), typeof(to_variant("GROSS_INCOME"))),
                                     'OCCUPATIONCODE', array_construct(to_varchar("OCCUPATION"), typeof(to_variant("OCCUPATION")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BJAZ_HCF_MEMBER_DTLS (stitch stitch_party_individual_demographics t4)
