                                     'DESIGNATION', array_construct(to_varchar("DESIGNATION"), typeof(to_variant("DESIGNATION"))),
                                     'OCCUPATIONCODE', array_construct(to_varchar("OCCUPATION"), typeof(to_variant("OCCUPATION")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 6. BJAZ_SH_MEM_DTLS_EXTN (stitch stitch_party_individual_demographics t7)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'ANNUALINCOME', array_construct(to_varchar("GROSS_INCOME"), typeof(to_variant("GROSS_INCOME"))),
                                     'OCCUPATIONCODE', array_construct(to_varchar("OCCUPATION"), typeof(to_variant("OCCUPATION")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 7. BJAZ_SPP_MEMBER_DTLS (stitch stitch_party_individual_demographics t8)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'OCCUPATIONCODE', array_construct(to_varchar("MEMBER_OCCUPATION"), typeof(to_variant("MEMBER_OCCUPATION")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 8. CP_PARTNERS (stitch stitch_party_individual_demographics t9)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
