      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
raw_vals as (
    -- 1. AZBJ_PARTNER_EXTN (stitch stitch_party_organisation_profile t0)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'GROUPNAME', array_construct(to_varchar("GLOBAL_CO_NAME"), typeof(to_variant("GLOBAL_CO_NAME"))),
                                     'INDUSTRYDESCRIPTION', array_construct(to_varchar("INDUSTRY"), typeof(to_variant("INDUSTRY"))),
                                     'MSMEINDICATOR', array_construct(to_varchar("MSME_FLAG"), typeof(to_variant("MSME_FLAG"))),
                                     'PAIDUPCAPITAL', array_construct(to_varchar("PAIDUP_CAPITAL"), typeof(to_variant("PAIDUP_CAPITAL"))),
                                     'PARENTENTITYNAME', array_construct(to_varchar("PARENT_CO"), typeof(to_variant("PARENT_CO")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_CLM_SUPP_EXTN (stitch stitch_party_organisation_profile t2)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN,
           lateral flatten(input => object_construct_keep_null(
