                                     'DATEOFINCORPORATION', array_construct(to_varchar("ESTABLISH_YEAR"), typeof(to_variant("ESTABLISH_YEAR"))),
                                     'MSMEINDICATOR', array_construct(to_varchar("MSME_CLASS"), typeof(to_variant("MSME_CLASS"))),
