-- 131. OPUS — SAT_PARTY_VEHICLE_PRIOR_INSURANCE   [Implemented]
-- 5 mapped column(s), 20 RAW column lineage row(s); 5 column(s) are 1:1 and
-- value-checked in (b). Static transform flags -- integer cast on load (decimals lost if
-- the RAW column has a scale): PREVIOUSSUMINSURED<-PREV_SUM_INSURED,
-- PREVIOUSSUMINSURED<-PREVIOUS_SI. converted to TIMESTAMP_NTZ on load:
-- CONTINUITYINDICATOR<-PREV_POLICY_SINCE. 8 RAW branch(es): BJAZ_CTNGY_PA_MEM_DTLS,
-- BJAZ_EC_MEM_DTLS_EXTN, BJAZ_HCF_MEMBER_DTLS, BJAZ_HC_PART_EXTN,
-- BJAZ_HLT_ENSURE_MEM_DTLS, BJAZ_PA_DETL_EXTN, BJAZ_SH_MEM_DTLS_EXTN,
-- BJAZ_SPP_MEMBER_DTLS.
----------------------------------------------------------------------------------------
-- SQL query (a) -- column type / length / precision / scale: RAW vs satellite
with lineage (sat_column, raw_db, raw_schema, raw_table, raw_column, transform_flags, transform) as (
    -- generated from the dbt models: every RAW column that feeds a satellite column
    select * from values
        ('PREVIOUSPOLICYNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CTNGY_PA_MEM_DTLS', 'PREVIOUS_POLICY_DETAILS', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PREVIOUS_POLICY_DETAILS"::varchar), '''')'),
        ('PREVIOUSEXPIRYDATE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_EC_MEM_DTLS_EXTN', 'PERV_POL_EXP_DATE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PERV_POL_EXP_DATE"::varchar), '''')'),
        ('PREVIOUSINSURERNAME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_EC_MEM_DTLS_EXTN', 'PREV_COMPANY_NAME', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PREV_COMPANY_NAME"::varchar), '''')'),
        ('PREVIOUSPOLICYNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_EC_MEM_DTLS_EXTN', 'PREV_POLICY_DTLS', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PREV_POLICY_DTLS"::varchar), '''')'),
        ('PREVIOUSSUMINSURED', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_EC_MEM_DTLS_EXTN', 'PREV_SUM_INSURED', 'SCALE0, SAT_VARCHAR', '("PREV_SUM_INSURED"::number)'),
        ('CONTINUITYINDICATOR', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HCF_MEMBER_DTLS', 'PREV_POLICY_SINCE', 'TO_TIMESTAMP, SAT_VARCHAR', '("PREV_POLICY_SINCE"::timestamp_ntz)'),
        ('PREVIOUSPOLICYNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HCF_MEMBER_DTLS', 'CONCURRENT_POLICY_DETAILS', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("CONCURRENT_POLICY_DETAILS"::varchar), '''')'),
        ('PREVIOUSSUMINSURED', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HCF_MEMBER_DTLS', 'PREVIOUS_SI', 'SCALE0, SAT_VARCHAR', '("PREVIOUS_SI"::number)'),
        ('PREVIOUSPOLICYNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HC_PART_EXTN', 'FIRST_POLICY_REF', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("FIRST_POLICY_REF"::varchar), '''')'),
        ('CONTINUITYINDICATOR', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HLT_ENSURE_MEM_DTLS', 'PREVIOUS_SINCE_NOOF_YEARS', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PREVIOUS_SINCE_NOOF_YEARS"::varchar), '''')'),
        ('PREVIOUSEXPIRYDATE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HLT_ENSURE_MEM_DTLS', 'PREVIOUS_TO_DATE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PREVIOUS_TO_DATE"::varchar), '''')'),
        ('PREVIOUSINSURERNAME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HLT_ENSURE_MEM_DTLS', 'PREVIOUS_COMPANY_NAME', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PREVIOUS_COMPANY_NAME"::varchar), '''')'),
        ('PREVIOUSPOLICYNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HLT_ENSURE_MEM_DTLS', 'PREV_POLICY_NO', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PREV_POLICY_NO"::varchar), '''')'),
        ('PREVIOUSSUMINSURED', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HLT_ENSURE_MEM_DTLS', 'PREVIOUS_SUM_INSURED', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PREVIOUS_SUM_INSURED"::varchar), '''')'),
        ('PREVIOUSPOLICYNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_PA_DETL_EXTN', 'FIRST_POLICY_REF', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("FIRST_POLICY_REF"::varchar), '''')'),
        ('PREVIOUSPOLICYNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SH_MEM_DTLS_EXTN', 'PREV_POLICY_DTLS', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PREV_POLICY_DTLS"::varchar), '''')'),
        ('PREVIOUSSUMINSURED', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SH_MEM_DTLS_EXTN', 'PREV_SUM_INSURED', 'SCALE0, SAT_VARCHAR', '("PREV_SUM_INSURED"::number)'),
        ('CONTINUITYINDICATOR', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SPP_MEMBER_DTLS', 'PREV_POLICY_SINCE', 'TO_TIMESTAMP, SAT_VARCHAR', '("PREV_POLICY_SINCE"::timestamp_ntz)'),
        ('PREVIOUSPOLICYNUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SPP_MEMBER_DTLS', 'CONCURRENT_POLICY_DETAILS', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("CONCURRENT_POLICY_DETAILS"::varchar), '''')'),
        ('PREVIOUSSUMINSURED', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SPP_MEMBER_DTLS', 'PREVIOUS_SI', 'SCALE0, SAT_VARCHAR', '("PREVIOUS_SI"::number)')
),
raw_cols as (
    select table_catalog, table_schema, table_name, column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'UTILS'
       and table_name in ('BJAZ_CTNGY_PA_MEM_DTLS', 'BJAZ_EC_MEM_DTLS_EXTN', 'BJAZ_HCF_MEMBER_DTLS', 'BJAZ_HC_PART_EXTN', 'BJAZ_HLT_ENSURE_MEM_DTLS', 'BJAZ_PA_DETL_EXTN', 'BJAZ_SH_MEM_DTLS_EXTN', 'BJAZ_SPP_MEMBER_DTLS')
),
sat_cols as (
    select column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'BGIL_DATA_MODEL'
       and table_name = 'SAT_PARTY_VEHICLE_PRIOR_INSURANCE'
)
select 'OPUS' as project, 'SAT_PARTY_VEHICLE_PRIOR_INSURANCE' as satellite,
       l.sat_column, case when s.data_type = 'TEXT' then 'TEXT(' || s.char_len || ')' when s.data_type = 'NUMBER' then 'NUMBER(' || s.num_prec || ',' || s.num_scale || ')' when s.data_type like 'TIMESTAMP%' then s.data_type || '(' || s.dt_prec || ')' else s.data_type end as sat_type,
       l.raw_table, l.raw_column, case when r.data_type = 'TEXT' then 'TEXT(' || r.char_len || ')' when r.data_type = 'NUMBER' then 'NUMBER(' || r.num_prec || ',' || r.num_scale || ')' when r.data_type like 'TIMESTAMP%' then r.data_type || '(' || r.dt_prec || ')' else r.data_type end as raw_type,
       l.transform_flags,
       case
         when r.data_type is null then 'FAIL - RAW COLUMN NOT FOUND'
         when s.data_type is null then 'FAIL - SAT COLUMN NOT FOUND'
         when r.data_type = 'NUMBER' and r.num_scale > 0 and l.transform_flags like '%SCALE0%'
              then 'FAIL - DECIMALS LOST (cast to integer NUMBER on load)'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER' and s.num_scale < r.num_scale then 'FAIL - DECIMALS LOST'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER'
              and s.num_prec - s.num_scale < r.num_prec - r.num_scale then 'FAIL - PRECISION RISK'
         when r.data_type = 'TEXT' and s.data_type = 'TEXT' and s.char_len < r.char_len then 'FAIL - TRUNCATION RISK (length)'
         when r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%' and s.dt_prec < r.dt_prec
              then 'FAIL - FRACTIONAL SECONDS TRUNCATED'
         when r.data_type = 'DATE' and s.data_type like 'TIMESTAMP%' then 'REVIEW - DATE LOADED AS TIMESTAMP'
         when r.data_type <> 'TEXT' and s.data_type = 'TEXT' then 'REVIEW - STORED AS TEXT (see query b)'
         when r.data_type = 'TEXT' and s.data_type <> 'TEXT' then 'REVIEW - TEXT CONVERTED TO ' || s.data_type
         when r.data_type <> s.data_type and not (r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%')
              then 'REVIEW - TYPE CHANGED'
         when l.transform_flags like '%TRIM%' then 'PASS (whitespace trimmed by design)'
         else 'PASS'
       end as type_verdict,
       l.transform
  from lineage l
  left join raw_cols r
         on r.table_catalog = l.raw_db and r.table_schema = l.raw_schema
        and r.table_name = l.raw_table and r.column_name = l.raw_column
  left join sat_cols s on s.column_name = l.sat_column
 order by l.sat_column, l.raw_table, l.raw_column;

-- SQL query (b) -- value format on the sample (1:1 mapped columns; run the ALTER SESSION first)
alter session set TIMESTAMP_NTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9',
                  TIMESTAMP_LTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  TIMESTAMP_TZ_OUTPUT_FORMAT  = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  DATE_OUTPUT_FORMAT          = 'YYYY-MM-DD';

with sat_rows as (
    -- this project's rows of the satellite
    select s.PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'PREVIOUSPOLICYNUMBER', to_varchar(s."PREVIOUSPOLICYNUMBER"),
               'PREVIOUSEXPIRYDATE', to_varchar(s."PREVIOUSEXPIRYDATE"),
               'PREVIOUSINSURERNAME', to_varchar(s."PREVIOUSINSURERNAME"),
               'PREVIOUSSUMINSURED', to_varchar(s."PREVIOUSSUMINSURED"),
               'CONTINUITYINDICATOR', to_varchar(s."CONTINUITYINDICATOR")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_VEHICLE_PRIOR_INSURANCE s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
raw_vals as (
    -- 1. BJAZ_CTNGY_PA_MEM_DTLS
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_CTNGY_PA_MEM_DTLS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'PREVIOUSPOLICYNUMBER', array_construct(to_varchar("PREVIOUS_POLICY_DETAILS"), typeof(to_variant("PREVIOUS_POLICY_DETAILS")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_EC_MEM_DTLS_EXTN
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_EC_MEM_DTLS_EXTN' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'PREVIOUSEXPIRYDATE', array_construct(to_varchar("PERV_POL_EXP_DATE"), typeof(to_variant("PERV_POL_EXP_DATE"))),
                                     'PREVIOUSINSURERNAME', array_construct(to_varchar("PREV_COMPANY_NAME"), typeof(to_variant("PREV_COMPANY_NAME"))),
                                     'PREVIOUSPOLICYNUMBER', array_construct(to_varchar("PREV_POLICY_DTLS"), typeof(to_variant("PREV_POLICY_DTLS"))),
                                     'PREVIOUSSUMINSURED', array_construct(to_varchar("PREV_SUM_INSURED"), typeof(to_variant("PREV_SUM_INSURED")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BJAZ_HCF_MEMBER_DTLS
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_HCF_MEMBER_DTLS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'CONTINUITYINDICATOR', array_construct(to_varchar("PREV_POLICY_SINCE"), typeof(to_variant("PREV_POLICY_SINCE"))),
                                     'PREVIOUSPOLICYNUMBER', array_construct(to_varchar("CONCURRENT_POLICY_DETAILS"), typeof(to_variant("CONCURRENT_POLICY_DETAILS"))),
                                     'PREVIOUSSUMINSURED', array_construct(to_varchar("PREVIOUS_SI"), typeof(to_variant("PREVIOUS_SI")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 4. BJAZ_HC_PART_EXTN
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_HC_PART_EXTN' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HC_PART_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'PREVIOUSPOLICYNUMBER', array_construct(to_varchar("FIRST_POLICY_REF"), typeof(to_variant("FIRST_POLICY_REF")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 5. BJAZ_HLT_ENSURE_MEM_DTLS
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_HLT_ENSURE_MEM_DTLS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HLT_ENSURE_MEM_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'CONTINUITYINDICATOR', array_construct(to_varchar("PREVIOUS_SINCE_NOOF_YEARS"), typeof(to_variant("PREVIOUS_SINCE_NOOF_YEARS"))),
                                     'PREVIOUSEXPIRYDATE', array_construct(to_varchar("PREVIOUS_TO_DATE"), typeof(to_variant("PREVIOUS_TO_DATE"))),
                                     'PREVIOUSINSURERNAME', array_construct(to_varchar("PREVIOUS_COMPANY_NAME"), typeof(to_variant("PREVIOUS_COMPANY_NAME"))),
                                     'PREVIOUSPOLICYNUMBER', array_construct(to_varchar("PREV_POLICY_NO"), typeof(to_variant("PREV_POLICY_NO"))),
                                     'PREVIOUSSUMINSURED', array_construct(to_varchar("PREVIOUS_SUM_INSURED"), typeof(to_variant("PREVIOUS_SUM_INSURED")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 6. BJAZ_PA_DETL_EXTN
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_PA_DETL_EXTN' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PA_DETL_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'PREVIOUSPOLICYNUMBER', array_construct(to_varchar("FIRST_POLICY_REF"), typeof(to_variant("FIRST_POLICY_REF")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 7. BJAZ_SH_MEM_DTLS_EXTN
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_SH_MEM_DTLS_EXTN' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'PREVIOUSPOLICYNUMBER', array_construct(to_varchar("PREV_POLICY_DTLS"), typeof(to_variant("PREV_POLICY_DTLS"))),
                                     'PREVIOUSSUMINSURED', array_construct(to_varchar("PREV_SUM_INSURED"), typeof(to_variant("PREV_SUM_INSURED")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 8. BJAZ_SPP_MEMBER_DTLS
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_SPP_MEMBER_DTLS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'CONTINUITYINDICATOR', array_construct(to_varchar("PREV_POLICY_SINCE"), typeof(to_variant("PREV_POLICY_SINCE"))),
                                     'PREVIOUSPOLICYNUMBER', array_construct(to_varchar("CONCURRENT_POLICY_DETAILS"), typeof(to_variant("CONCURRENT_POLICY_DETAILS"))),
                                     'PREVIOUSSUMINSURED', array_construct(to_varchar("PREVIOUS_SI"), typeof(to_variant("PREVIOUS_SI")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
),
classified as (
    select v.hkey, v.rs, v.col,
           case
             when equal_null(v.val, r.raw_value) then 0                                                  -- EXACT
             when v.val is null and nullif(trim(r.raw_value), '') is null then 1                         -- BLANK -> NULL (by design)
             when v.val = trim(r.raw_value) then 1                                                       -- WHITESPACE TRIMMED (by design)
             when r.raw_type <> 'VARCHAR' and v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 2             -- TYPED VALUE KEPT, TEXT FORM DIFFERS
             when r.raw_type <> 'VARCHAR' and try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 2
             when v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 3             -- DATE/TIME RE-FORMATTED
             when try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 3             -- NUMBER RE-FORMATTED
             when try_to_decimal(r.raw_value, 38, 12) <> round(try_to_decimal(r.raw_value, 38, 12), 0)
                  and try_to_decimal(v.val, 38, 12) = round(try_to_decimal(r.raw_value, 38, 12), 0) then 4  -- DECIMALS LOST
             when startswith(r.raw_value, v.val) then 5                                                  -- TRUNCATED
             else 6                                                                            -- DIFFERENT VALUE
           end as cls
      from sat_cols v
      join raw_vals r on r.hkey = v.hkey and r.rs_key = v.rs_key and r.col = v.col
),
best as (
    -- a key can have several RAW rows: keep the closest one per (unit, column)
    select hkey, rs, col, min(cls) as cls from classified group by hkey, rs, col
)
select 'OPUS' as project, 'SAT_PARTY_VEHICLE_PRIOR_INSURANCE' as satellite, col as sat_column,
       count(*)              as compared,
       count_if(cls = 0)     as exact,
       count_if(cls = 1)     as trimmed_or_blank_to_null,
       count_if(cls = 2)     as typed_value_kept_text_differs,
       count_if(cls = 3)     as reformatted,
       count_if(cls = 4)     as decimals_lost,
       count_if(cls = 5)     as truncated,
       count_if(cls = 6)     as different_value,
       case when count_if(cls in (3, 4, 5)) > 0 then 'FAIL'
            when count_if(cls = 6) > 0 then 'REVIEW (value differs - see DM-A2)'
            when count_if(cls = 1) > 0 then 'PASS (whitespace / blank->null by design)'
            else 'PASS' end  as format_status
  from best
 group by col
 order by col;



----------------------------------------------------------------------------------------
-- 132. OPUS — SAT_POLICY_BONUS_TRACKING   [Implemented]
-- 2 mapped column(s), 11 RAW column lineage row(s); 2 column(s) are 1:1 and
-- value-checked in (b). Static transform flags -- integer cast on load (decimals lost if
-- the RAW column has a scale): BONUSAMOUNT<-CUMULATIVE_AMT, BONUSAMOUNT<-BONUS_SI,
-- BONUSAMOUNT<-CUMM_BONUS, CUMULATIVEBONUSPERCENTAGE<-PRE_POL_NCB_PER,
-- CUMULATIVEBONUSPERCENTAGE<-CUMULATIVE_BNOUZ_PER,
-- CUMULATIVEBONUSPERCENTAGE<-CUMM_BONUS_PER. 1 RAW branch(es): stitch
-- stitch_policy_bonus_tracking. stitch_policy_bonus_tracking reproduced from 7 RAW
-- tables with no watermark window; every row combination per key is kept because the
-- stitch keeps one of them arbitrarily.
----------------------------------------------------------------------------------------
-- SQL query (a) -- column type / length / precision / scale: RAW vs satellite
with lineage (sat_column, raw_db, raw_schema, raw_table, raw_column, transform_flags, transform) as (
    -- generated from the dbt models: every RAW column that feeds a satellite column
    select * from values
        ('BONUSAMOUNT', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HCF_MEMBER_DTLS', 'CUMULATIVE_AMT', 'TRIM, BLANK->NULL, SCALE0', 'nullif(trim(to_varchar(("CUMULATIVE_AMT"::number))), '''')'),
        ('BONUSAMOUNT', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HLT_ENSURE_MEM_DTLS', 'PREVIOUS_CUM_BONUS', 'TRIM, BLANK->NULL', 'nullif(trim(to_varchar(nullif(trim("PREVIOUS_CUM_BONUS"::varchar), ''''))), '''')'),
        ('BONUSAMOUNT', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HM_MEMBER_DTLS', 'BONUS_SI', 'TRIM, BLANK->NULL, SCALE0', 'nullif(trim(to_varchar(("BONUS_SI"::number))), '''')'),
        ('BONUSAMOUNT', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_PA_DETL_EXTN', 'CUMMULATIVE_BONUS', 'TRIM, BLANK->NULL', 'nullif(trim(to_varchar(nullif(trim("CUMMULATIVE_BONUS"::varchar), ''''))), '''')'),
        ('BONUSAMOUNT', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SH_MEM_DTLS_EXTN', 'CUMM_BONUS', 'TRIM, BLANK->NULL, SCALE0', 'nullif(trim(to_varchar(("CUMM_BONUS"::number))), '''')'),
        ('BONUSAMOUNT', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SPP_MEMBER_DTLS', 'CUMULATIVE_AMT', 'TRIM, BLANK->NULL, SCALE0', 'nullif(trim(to_varchar(("CUMULATIVE_AMT"::number))), '''')'),
        ('CUMULATIVEBONUSPERCENTAGE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_EC_MEM_DTLS_EXTN', 'PRE_POL_NCB_PER', 'TRIM, BLANK->NULL, SCALE0', 'nullif(trim(to_varchar(("PRE_POL_NCB_PER"::number))), '''')'),
        ('CUMULATIVEBONUSPERCENTAGE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HCF_MEMBER_DTLS', 'CUMULATIVE_BNOUZ_PER', 'TRIM, BLANK->NULL, SCALE0', 'nullif(trim(to_varchar(("CUMULATIVE_BNOUZ_PER"::number))), '''')'),
        ('CUMULATIVEBONUSPERCENTAGE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HM_MEMBER_DTLS', 'CUMM_BONUS_PER', 'TRIM, BLANK->NULL, SCALE0', 'nullif(trim(to_varchar(("CUMM_BONUS_PER"::number))), '''')'),
        ('CUMULATIVEBONUSPERCENTAGE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SH_MEM_DTLS_EXTN', 'CUMM_BONUS_PER', 'TRIM, BLANK->NULL, SCALE0', 'nullif(trim(to_varchar(("CUMM_BONUS_PER"::number))), '''')'),
        ('CUMULATIVEBONUSPERCENTAGE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SPP_MEMBER_DTLS', 'CUMULATIVE_BNOUZ_PER', 'TRIM, BLANK->NULL, SCALE0', 'nullif(trim(to_varchar(("CUMULATIVE_BNOUZ_PER"::number))), '''')')
),
raw_cols as (
    select table_catalog, table_schema, table_name, column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'UTILS'
       and table_name in ('BJAZ_EC_MEM_DTLS_EXTN', 'BJAZ_HCF_MEMBER_DTLS', 'BJAZ_HLT_ENSURE_MEM_DTLS', 'BJAZ_HM_MEMBER_DTLS', 'BJAZ_PA_DETL_EXTN', 'BJAZ_SH_MEM_DTLS_EXTN', 'BJAZ_SPP_MEMBER_DTLS')
),
sat_cols as (
    select column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'BGIL_DATA_MODEL'
       and table_name = 'SAT_POLICY_BONUS_TRACKING'
)
select 'OPUS' as project, 'SAT_POLICY_BONUS_TRACKING' as satellite,
       l.sat_column, case when s.data_type = 'TEXT' then 'TEXT(' || s.char_len || ')' when s.data_type = 'NUMBER' then 'NUMBER(' || s.num_prec || ',' || s.num_scale || ')' when s.data_type like 'TIMESTAMP%' then s.data_type || '(' || s.dt_prec || ')' else s.data_type end as sat_type,
       l.raw_table, l.raw_column, case when r.data_type = 'TEXT' then 'TEXT(' || r.char_len || ')' when r.data_type = 'NUMBER' then 'NUMBER(' || r.num_prec || ',' || r.num_scale || ')' when r.data_type like 'TIMESTAMP%' then r.data_type || '(' || r.dt_prec || ')' else r.data_type end as raw_type,
       l.transform_flags,
       case
         when r.data_type is null then 'FAIL - RAW COLUMN NOT FOUND'
         when s.data_type is null then 'FAIL - SAT COLUMN NOT FOUND'
         when r.data_type = 'NUMBER' and r.num_scale > 0 and l.transform_flags like '%SCALE0%'
              then 'FAIL - DECIMALS LOST (cast to integer NUMBER on load)'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER' and s.num_scale < r.num_scale then 'FAIL - DECIMALS LOST'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER'
              and s.num_prec - s.num_scale < r.num_prec - r.num_scale then 'FAIL - PRECISION RISK'
         when r.data_type = 'TEXT' and s.data_type = 'TEXT' and s.char_len < r.char_len then 'FAIL - TRUNCATION RISK (length)'
         when r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%' and s.dt_prec < r.dt_prec
              then 'FAIL - FRACTIONAL SECONDS TRUNCATED'
         when r.data_type = 'DATE' and s.data_type like 'TIMESTAMP%' then 'REVIEW - DATE LOADED AS TIMESTAMP'
         when r.data_type <> 'TEXT' and s.data_type = 'TEXT' then 'REVIEW - STORED AS TEXT (see query b)'
         when r.data_type = 'TEXT' and s.data_type <> 'TEXT' then 'REVIEW - TEXT CONVERTED TO ' || s.data_type
         when r.data_type <> s.data_type and not (r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%')
              then 'REVIEW - TYPE CHANGED'
         when l.transform_flags like '%TRIM%' then 'PASS (whitespace trimmed by design)'
         else 'PASS'
       end as type_verdict,
       l.transform
  from lineage l
  left join raw_cols r
         on r.table_catalog = l.raw_db and r.table_schema = l.raw_schema
        and r.table_name = l.raw_table and r.column_name = l.raw_column
  left join sat_cols s on s.column_name = l.sat_column
 order by l.sat_column, l.raw_table, l.raw_column;

-- SQL query (b) -- value format on the sample (1:1 mapped columns; run the ALTER SESSION first)
alter session set TIMESTAMP_NTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9',
                  TIMESTAMP_LTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  TIMESTAMP_TZ_OUTPUT_FORMAT  = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  DATE_OUTPUT_FORMAT          = 'YYYY-MM-DD';

with sat_rows as (
    -- this project's rows of the satellite
    select s.POLICY_HKEY as hkey, s.RECORD_SOURCE as rs, 'STITCH' as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'CUMULATIVEBONUSPERCENTAGE', to_varchar(s."CUMULATIVEBONUSPERCENTAGE"),
               'BONUSAMOUNT', to_varchar(s."BONUSAMOUNT")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_BONUS_TRACKING s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
raw_vals as (
    -- 1. BJAZ_EC_MEM_DTLS_EXTN (stitch stitch_policy_bonus_tracking t0)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'CUMULATIVEBONUSPERCENTAGE', array_construct(to_varchar("PRE_POL_NCB_PER"), typeof(to_variant("PRE_POL_NCB_PER")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_HCF_MEMBER_DTLS (stitch stitch_policy_bonus_tracking t1)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'BONUSAMOUNT', array_construct(to_varchar("CUMULATIVE_AMT"), typeof(to_variant("CUMULATIVE_AMT"))),
                                     'CUMULATIVEBONUSPERCENTAGE', array_construct(to_varchar("CUMULATIVE_BNOUZ_PER"), typeof(to_variant("CUMULATIVE_BNOUZ_PER")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BJAZ_HLT_ENSURE_MEM_DTLS (stitch stitch_policy_bonus_tracking t2)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HLT_ENSURE_MEM_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'BONUSAMOUNT', array_construct(to_varchar("PREVIOUS_CUM_BONUS"), typeof(to_variant("PREVIOUS_CUM_BONUS")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 4. BJAZ_HM_MEMBER_DTLS (stitch stitch_policy_bonus_tracking t3)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'BONUSAMOUNT', array_construct(to_varchar("BONUS_SI"), typeof(to_variant("BONUS_SI"))),
                                     'CUMULATIVEBONUSPERCENTAGE', array_construct(to_varchar("CUMM_BONUS_PER"), typeof(to_variant("CUMM_BONUS_PER")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 5. BJAZ_PA_DETL_EXTN (stitch stitch_policy_bonus_tracking t4)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PA_DETL_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'BONUSAMOUNT', array_construct(to_varchar("CUMMULATIVE_BONUS"), typeof(to_variant("CUMMULATIVE_BONUS")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 6. BJAZ_SH_MEM_DTLS_EXTN (stitch stitch_policy_bonus_tracking t5)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'BONUSAMOUNT', array_construct(to_varchar("CUMM_BONUS"), typeof(to_variant("CUMM_BONUS"))),
                                     'CUMULATIVEBONUSPERCENTAGE', array_construct(to_varchar("CUMM_BONUS_PER"), typeof(to_variant("CUMM_BONUS_PER")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 7. BJAZ_SPP_MEMBER_DTLS (stitch stitch_policy_bonus_tracking t6)
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'BONUSAMOUNT', array_construct(to_varchar("CUMULATIVE_AMT"), typeof(to_variant("CUMULATIVE_AMT"))),
                                     'CUMULATIVEBONUSPERCENTAGE', array_construct(to_varchar("CUMULATIVE_BNOUZ_PER"), typeof(to_variant("CUMULATIVE_BNOUZ_PER")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
),
classified as (
    select v.hkey, v.rs, v.col,
           case
             when equal_null(v.val, r.raw_value) then 0                                                  -- EXACT
             when v.val is null and nullif(trim(r.raw_value), '') is null then 1                         -- BLANK -> NULL (by design)
             when v.val = trim(r.raw_value) then 1                                                       -- WHITESPACE TRIMMED (by design)
             when r.raw_type <> 'VARCHAR' and v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 2             -- TYPED VALUE KEPT, TEXT FORM DIFFERS
             when r.raw_type <> 'VARCHAR' and try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 2
             when v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 3             -- DATE/TIME RE-FORMATTED
             when try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 3             -- NUMBER RE-FORMATTED
             when try_to_decimal(r.raw_value, 38, 12) <> round(try_to_decimal(r.raw_value, 38, 12), 0)
                  and try_to_decimal(v.val, 38, 12) = round(try_to_decimal(r.raw_value, 38, 12), 0) then 4  -- DECIMALS LOST
             when startswith(r.raw_value, v.val) then 5                                                  -- TRUNCATED
             else 6                                                                            -- DIFFERENT VALUE
           end as cls
      from sat_cols v
      join raw_vals r on r.hkey = v.hkey and r.rs_key = v.rs_key and r.col = v.col
),
best as (
    -- a key can have several RAW rows: keep the closest one per (unit, column)
    select hkey, rs, col, min(cls) as cls from classified group by hkey, rs, col
)
select 'OPUS' as project, 'SAT_POLICY_BONUS_TRACKING' as satellite, col as sat_column,
       count(*)              as compared,
       count_if(cls = 0)     as exact,
       count_if(cls = 1)     as trimmed_or_blank_to_null,
       count_if(cls = 2)     as typed_value_kept_text_differs,
       count_if(cls = 3)     as reformatted,
       count_if(cls = 4)     as decimals_lost,
       count_if(cls = 5)     as truncated,
       count_if(cls = 6)     as different_value,
       case when count_if(cls in (3, 4, 5)) > 0 then 'FAIL'
            when count_if(cls = 6) > 0 then 'REVIEW (value differs - see DM-A2)'
            when count_if(cls = 1) > 0 then 'PASS (whitespace / blank->null by design)'
            else 'PASS' end  as format_status
  from best
 group by col
 order by col;



