        ('POLICYREFERENCENUMBER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HM_MEMBER_DTLS', 'POLICY_REF', 'TRIM, BLANK->NULL', 'nullif(trim(to_varchar(nullif(trim("POLICY_REF"::varchar), ''''))), '''')'),
