        ('RISKINCEPTIONDATE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_PA_DETL_EXTN', 'INCEPTION_DATE', 'TRIM, BLANK->NULL, TO_TIMESTAMP', 'nullif(trim(to_varchar(("INCEPTION_DATE"::timestamp_ntz))), '''')'),
        ('RISKINCEPTIONDATE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SH_MEM_DTLS_EXTN', 'EFFETIVE_DATE', 'TRIM, BLANK->NULL, TO_TIMESTAMP', 'nullif(trim(to_varchar(("EFFETIVE_DATE"::timestamp_ntz))), '''')'),
        ('RISKINCEPTIONDATE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SPP_MEMBER_DTLS', 'FROM_DATE', 'TRIM, BLANK->NULL, TO_TIMESTAMP', 'nullif(trim(to_varchar(("FROM_DATE"::timestamp_ntz))), '''')')
),
raw_cols as (
    select table_catalog, table_schema, table_name, column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'UTILS'
       and table_name in ('AZBJ_PARTNER_EXTN', 'BJAZ_CTNGY_GC_MEM_DATA', 'BJAZ_CTNGY_PA_MEM_DTLS', 'BJAZ_EC_MEM_DTLS_EXTN', 'BJAZ_HCF_MEMBER_DTLS', 'BJAZ_HC_PART_EXTN', 'BJAZ_HM_MEMBER_DTLS', 'BJAZ_PA_DETL_EXTN', 'BJAZ_SH_MEM_DTLS_EXTN', 'BJAZ_SPP_MEMBER_DTLS')
),
sat_cols as (
