        ('TARIFFRATE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HM_HOSPITAL_MASTER', 'IMPS_PAYMENT_LMT', 'SCALE0', '("IMPS_PAYMENT_LMT"::number)')
),
