        ('VERIFIED_DATE_OF_BIRTH', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_AUTH', 'AUTH_DOB', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("AUTH_DOB"::varchar), '''')'),
        ('VERIFIED_FATHER_NAME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_AUTH', 'AUTH_FATHER_NAME', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("AUTH_FATHER_NAME"::varchar), '''')'),
        ('VERIFIED_FULL_NAME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_AUTH', 'AUTH_FULL_NAME', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("AUTH_FULL_NAME"::varchar), '''')'),
        ('VERIFIED_GENDER_CODE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_AUTH', 'AUTH_GENDER', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("AUTH_GENDER"::varchar), '''')'),
        ('VERIFIED_DATE_OF_BIRTH', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_DETAILS', 'RESPONSE_DOB', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("RESPONSE_DOB"::varchar), '''')'),
        ('VERIFIED_FULL_NAME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_DETAILS', 'POI_RESPONSE_FULL_NAME', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("POI_RESPONSE_FULL_NAME"::varchar), '''')'),
        ('VERIFICATION_MATCH_SCORE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_NAME_MATCH', 'SCORE', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("SCORE"::varchar), '''')'),
        ('VERIFICATION_REQUESTED_NAME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_NAME_MATCH', 'REQUEST_NAME', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("REQUEST_NAME"::varchar), '''')'),
        ('VERIFICATION_RESPONSE_DATE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_NAME_MATCH', 'RESPONSE_DATE', 'TO_TIMESTAMP, SAT_VARCHAR', 'try_to_timestamp_ntz(regexp_replace("RESPONSE_DATE"::varchar, ''^Z[ ]*'', ''''))'),
        ('VERIFICATION_RETURNED_NAME', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_NAME_MATCH', 'RESPONSE_NAME', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("RESPONSE_NAME"::varchar), '''')'),
        ('PERFORM_KYC_VERIFICATION_CONSENT_INDICATOR', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_OCR', 'CUSTOMER_KYC_CONSENT', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("CUSTOMER_KYC_CONSENT"::varchar), '''')'),
        ('USE_POA_NAME_AS_POLICY_NAME_CONSENT_INDICATOR', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_OCR', 'POA_POLICY_NAME_CONSENT', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("POA_POLICY_NAME_CONSENT"::varchar), '''')'),
        ('USE_POI_NAME_AS_POLICY_NAME_CONSENT_INDICATOR', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_T_KYC_OCR', 'POI_POLICY_NAME_CONSENT', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("POI_POLICY_NAME_CONSENT"::varchar), '''')')
),
raw_cols as (
    select table_catalog, table_schema, table_name, column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'UTILS'
       and table_name in ('BJAZ_M_KYC_DRIVING_LICENCE', 'BJAZ_M_KYC_GSTN', 'BJAZ_M_KYC_PAN', 'BJAZ_M_KYC_PASSPORT', 'BJAZ_M_KYC_VOTER', 'BJAZ_T_CKYC_PERSONAL_DTLS', 'BJAZ_T_CKYC_REL_PERSION_DTLS', 'BJAZ_T_CKYC_SEARCH', 'BJAZ_T_EKYC', 'BJAZ_T_KYC_AUTH', 'BJAZ_T_KYC_DETAILS', 'BJAZ_T_KYC_NAME_MATCH', 'BJAZ_T_KYC_OCR')
),
sat_cols as (
    select column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'BGIL_DATA_MODEL'
       and table_name = 'SAT_AUG_KYC_PARTY'
)
select 'OPUS' as project, 'SAT_AUG_KYC_PARTY' as satellite,
       l.sat_column, case when s.data_type = 'TEXT' then 'TEXT(' || s.char_len || ')' when s.data_type = 'NUMBER' then 'NUMBER(' || s.num_prec || ',' || s.num_scale || ')' when s.data_type like 'TIMESTAMP%' then s.data_type || '(' || s.dt_prec || ')' else s.data_type end as sat_type,
       l.raw_table, l.raw_column, case when r.data_type = 'TEXT' then 'TEXT(' || r.char_len || ')' when r.data_type = 'NUMBER' then 'NUMBER(' || r.num_prec || ',' || r.num_scale || ')' when r.data_type like 'TIMESTAMP%' then r.data_type || '(' || r.dt_prec || ')' else r.data_type end as raw_type,
       l.transform_flags,
       case
         when r.data_type is null then 'FAIL - RAW COLUMN NOT FOUND'
         when s.data_type is null then 'FAIL - SAT COLUMN NOT FOUND'
         when r.data_type = 'NUMBER' and r.num_scale > 0 and l.transform_flags like '%SCALE0%'
              then 'FAIL - DECIMALS LOST (cast to integer NUMBER on load)'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER' and s.num_scale < r.num_scale then 'FAIL - DECIMALS LOST'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER'
              and s.num_prec - s.num_scale < r.num_prec - r.num_scale then 'FAIL - PRECISION RISK'
         when r.data_type = 'TEXT' and s.data_type = 'TEXT' and s.char_len < r.char_len then 'FAIL - TRUNCATION RISK (length)'
         when r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%' and s.dt_prec < r.dt_prec
              then 'FAIL - FRACTIONAL SECONDS TRUNCATED'
         when r.data_type = 'DATE' and s.data_type like 'TIMESTAMP%' then 'REVIEW - DATE LOADED AS TIMESTAMP'
         when r.data_type <> 'TEXT' and s.data_type = 'TEXT' then 'REVIEW - STORED AS TEXT (see query b)'
         when r.data_type = 'TEXT' and s.data_type <> 'TEXT' then 'REVIEW - TEXT CONVERTED TO ' || s.data_type
         when r.data_type <> s.data_type and not (r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%')
              then 'REVIEW - TYPE CHANGED'
         when l.transform_flags like '%TRIM%' then 'PASS (whitespace trimmed by design)'
         else 'PASS'
       end as type_verdict,
       l.transform
  from lineage l
  left join raw_cols r
         on r.table_catalog = l.raw_db and r.table_schema = l.raw_schema
        and r.table_name = l.raw_table and r.column_name = l.raw_column
  left join sat_cols s on s.column_name = l.sat_column
 order by l.sat_column, l.raw_table, l.raw_column;

-- SQL query (b) -- value format on the sample (1:1 mapped columns; run the ALTER SESSION first)
alter session set TIMESTAMP_NTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9',
                  TIMESTAMP_LTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  TIMESTAMP_TZ_OUTPUT_FORMAT  = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  DATE_OUTPUT_FORMAT          = 'YYYY-MM-DD';

with sat_rows as (
    -- this project's rows of the satellite
    select s.PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'VERIFICATION_RESULT_VALID_UNTIL_DATE', to_varchar(s."VERIFICATION_RESULT_VALID_UNTIL_DATE"),
               'VERIFIED_CITIZENSHIP', to_varchar(s."VERIFIED_CITIZENSHIP"),
               'VERIFIED_DATE_OF_BIRTH', to_varchar(s."VERIFIED_DATE_OF_BIRTH"),
               'VERIFIED_FATHER_NAME', to_varchar(s."VERIFIED_FATHER_NAME"),
               'VERIFIED_FULL_NAME', to_varchar(s."VERIFIED_FULL_NAME"),
               'VERIFIED_GENDER_CODE', to_varchar(s."VERIFIED_GENDER_CODE"),
               'VERIFIED_LEGAL_NAME', to_varchar(s."VERIFIED_LEGAL_NAME"),
               'VERIFIED_TRADE_NAME', to_varchar(s."VERIFIED_TRADE_NAME"),
               'VERIFIED_GIVEN_NAME', to_varchar(s."VERIFIED_GIVEN_NAME"),
               'VERIFIED_SURNAME', to_varchar(s."VERIFIED_SURNAME"),
               'VERIFIED_AGE', to_varchar(s."VERIFIED_AGE"),
               'VERIFIED_RELATIVE_NAME', to_varchar(s."VERIFIED_RELATIVE_NAME"),
               'DOCUMENT_IMAGE_COUNT', to_varchar(s."DOCUMENT_IMAGE_COUNT"),
               'IN_PERSON_VERIFICATION_INDICATOR', to_varchar(s."IN_PERSON_VERIFICATION_INDICATOR"),
               'LOCAL_ADDRESS_RECORD_COUNT', to_varchar(s."LOCAL_ADDRESS_RECORD_COUNT"),
               'RELATED_PERSON_COUNT', to_varchar(s."RELATED_PERSON_COUNT"),
               'KYC_DECLARATION_PLACE', to_varchar(s."KYC_DECLARATION_PLACE"),
               'VERIFICATION_RESPONSE_CODE', to_varchar(s."VERIFICATION_RESPONSE_CODE"),
               'VERIFICATION_RESPONSE_MESSAGE', to_varchar(s."VERIFICATION_RESPONSE_MESSAGE"),
               'VERIFICATION_MATCH_SCORE', to_varchar(s."VERIFICATION_MATCH_SCORE"),
               'VERIFICATION_REQUESTED_NAME', to_varchar(s."VERIFICATION_REQUESTED_NAME"),
               'VERIFICATION_RESPONSE_DATE', to_varchar(s."VERIFICATION_RESPONSE_DATE"),
               'VERIFICATION_RETURNED_NAME', to_varchar(s."VERIFICATION_RETURNED_NAME"),
               'PERFORM_KYC_VERIFICATION_CONSENT_INDICATOR', to_varchar(s."PERFORM_KYC_VERIFICATION_CONSENT_INDICATOR"),
               'USE_POA_NAME_AS_POLICY_NAME_CONSENT_INDICATOR', to_varchar(s."USE_POA_NAME_AS_POLICY_NAME_CONSENT_INDICATOR"),
               'USE_POI_NAME_AS_POLICY_NAME_CONSENT_INDICATOR', to_varchar(s."USE_POI_NAME_AS_POLICY_NAME_CONSENT_INDICATOR")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_KYC_PARTY s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
raw_vals as (
    -- 1. BJAZ_M_KYC_DRIVING_LICENCE
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif('LICENCE:' || upper(trim(coalesce(nullif(trim("LICENCE_NUMBER"::varchar), ''),''))), 'LICENCE:'))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_M_KYC_DRIVING_LICENCE' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_DRIVING_LICENCE,
           lateral flatten(input => object_construct_keep_null(
                                     'VERIFICATION_RESULT_VALID_UNTIL_DATE', array_construct(to_varchar("EXPIRY_DATE"), typeof(to_variant("EXPIRY_DATE"))),
                                     'VERIFIED_CITIZENSHIP', array_construct(to_varchar("CITIZENSHIP"), typeof(to_variant("CITIZENSHIP"))),
                                     'VERIFIED_DATE_OF_BIRTH', array_construct(to_varchar("DOB"), typeof(to_variant("DOB"))),
                                     'VERIFIED_FATHER_NAME', array_construct(to_varchar("FATHER_NAME"), typeof(to_variant("FATHER_NAME"))),
                                     'VERIFIED_FULL_NAME', array_construct(to_varchar("NAME"), typeof(to_variant("NAME"))),
                                     'VERIFIED_GENDER_CODE', array_construct(to_varchar("GENDER"), typeof(to_variant("GENDER")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
