           'OPUS_BJAZ_M_KYC_PASSPORT' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_PASSPORT,
           lateral flatten(input => object_construct_keep_null(
                                     'VERIFICATION_RESULT_VALID_UNTIL_DATE', array_construct(to_varchar("EXPIRY_DATE"), typeof(to_variant("EXPIRY_DATE"))),
                                     'VERIFIED_DATE_OF_BIRTH', array_construct(to_varchar("DOB"), typeof(to_variant("DOB"))),
                                     'VERIFIED_FULL_NAME', array_construct(to_varchar("FULL_NAME"), typeof(to_variant("FULL_NAME"))),
                                     'VERIFIED_GIVEN_NAME', array_construct(to_varchar("NAME"), typeof(to_variant("NAME"))),
                                     'VERIFIED_SURNAME', array_construct(to_varchar("SURNAME"), typeof(to_variant("SURNAME")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 5. BJAZ_M_KYC_VOTER
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif('VOTER:' || upper(trim(coalesce(nullif(trim("VOTER_NUMBER"::varchar), ''),''))), 'VOTER:'))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_M_KYC_VOTER' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_VOTER,
           lateral flatten(input => object_construct_keep_null(
                                     'VERIFICATION_RESULT_VALID_UNTIL_DATE', array_construct(to_varchar("EXPIRY_DATE"), typeof(to_variant("EXPIRY_DATE"))),
                                     'VERIFIED_AGE', array_construct(to_varchar("AGE"), typeof(to_variant("AGE"))),
                                     'VERIFIED_FULL_NAME', array_construct(to_varchar("NAME"), typeof(to_variant("NAME"))),
                                     'VERIFIED_GENDER_CODE', array_construct(to_varchar("GENDER"), typeof(to_variant("GENDER"))),
                                     'VERIFIED_RELATIVE_NAME', array_construct(to_varchar("RELATIVE_NAME"), typeof(to_variant("RELATIVE_NAME")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
