               'EXP_LOB_LOSS_PROFIT_FLG', to_varchar(s."EXP_LOB_LOSS_PROFIT_FLG"),
               'EXP_LOB_MARINE_HULL_FLG', to_varchar(s."EXP_LOB_MARINE_HULL_FLG"),
               'EXP_LOB_MARIN_CARGO_FLG', to_varchar(s."EXP_LOB_MARIN_CARGO_FLG"),
               'EXP_LOB_MISCELL_FLG', to_varchar(s."EXP_LOB_MISCELL_FLG"),
               'EXP_LOB_MOTOR_FLG', to_varchar(s."EXP_LOB_MOTOR_FLG"),
               'EXP_LOB_WORKMAN_COMP_FLG', to_varchar(s."EXP_LOB_WORKMAN_COMP_FLG"),
               'GRADE', to_varchar(s."GRADE"),
               'INVOICE_PATTERN', to_varchar(s."INVOICE_PATTERN"),
