        ('WEBSITE_URL', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_INTERMEDIARY', 'WEBSITE_LINK', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("WEBSITE_LINK"::varchar), '''')'),
