        ('BMI_FLAG', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HCF_MEMBER_DTLS', 'BMI_FLAG', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("BMI_FLAG"::varchar), '''')'),
        ('BMI', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SPP_MEMBER_DTLS', 'BMI', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("BMI"::varchar), '''')'),
        ('HEIGHT_FEET', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SPP_MEMBER_DTLS', 'HEIGHT_FEET', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("HEIGHT_FEET"::varchar), '''')'),
        ('HEIGHT_INCHES', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SPP_MEMBER_DTLS', 'HEIGHT_INCHES', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("HEIGHT_INCHES"::varchar), '''')'),
        ('OTHER_OCC', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SPP_MEMBER_DTLS', 'OTHER_OCC', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("OTHER_OCC"::varchar), '''')'),
        ('DATE_OF_BIRTH_M', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HC_PART_EXTN', 'DATE_OF_BIRTH_M', 'TO_TIMESTAMP, SAT_VARCHAR', '("DATE_OF_BIRTH_M"::timestamp_ntz)'),
        ('CAUSE_OF_DEATH', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'CP_PARTNERS', 'CAUSE_OF_DEATH', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("CAUSE_OF_DEATH"::varchar), '''')'),
