        ('MARRIAGE_ANNIVERSARY_DATE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CLM_SUPP_EXTN', 'MRG_ANNIVERSIRY', 'TO_TIMESTAMP, SAT_VARCHAR', '("MRG_ANNIVERSIRY"::timestamp_ntz)'),
        ('PAN_ACK_DT', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_CLM_SUPP_EXTN', 'PAN_ACK_DT', 'TO_TIMESTAMP, SAT_VARCHAR', '("PAN_ACK_DT"::timestamp_ntz)'),
