               'BMI', to_varchar(s."BMI"),
               'HEIGHT_FEET', to_varchar(s."HEIGHT_FEET"),
               'HEIGHT_INCHES', to_varchar(s."HEIGHT_INCHES"),
               'OTHER_OCC', to_varchar(s."OTHER_OCC"),
               'DATE_OF_BIRTH_M', to_varchar(s."DATE_OF_BIRTH_M"),
               'CAUSE_OF_DEATH', to_varchar(s."CAUSE_OF_DEATH"),
               'PROOF_OF_DEATH_TYPE', to_varchar(s."PROOF_OF_DEATH_TYPE"),
               'ADHAAR_PAN_LINK_FLAG', to_varchar(s."ADHAAR_PAN_LINK_FLAG"),
