                                     'SMOKE_CONSUMP', array_construct(to_varchar("SMOKE_CONSUMP"), typeof(to_variant("SMOKE_CONSUMP")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 4. BJAZ_HCF_MEMBER_DTLS
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_HCF_MEMBER_DTLS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'BMI_FLAG', array_construct(to_varchar("BMI_FLAG"), typeof(to_variant("BMI_FLAG")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 5. BJAZ_SPP_MEMBER_DTLS
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_SPP_MEMBER_DTLS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'BMI', array_construct(to_varchar("BMI"), typeof(to_variant("BMI"))),
                                     'HEIGHT_FEET', array_construct(to_varchar("HEIGHT_FEET"), typeof(to_variant("HEIGHT_FEET"))),
                                     'HEIGHT_INCHES', array_construct(to_varchar("HEIGHT_INCHES"), typeof(to_variant("HEIGHT_INCHES"))),
                                     'OTHER_OCC', array_construct(to_varchar("OTHER_OCC"), typeof(to_variant("OTHER_OCC")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 6. BJAZ_HC_PART_EXTN
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_HC_PART_EXTN' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HC_PART_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'DATE_OF_BIRTH_M', array_construct(to_varchar("DATE_OF_BIRTH_M"), typeof(to_variant("DATE_OF_BIRTH_M")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 7. CP_PARTNERS
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_CP_PARTNERS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.CP_PARTNERS,
           lateral flatten(input => object_construct_keep_null(
                                     'CAUSE_OF_DEATH', array_construct(to_varchar("CAUSE_OF_DEATH"), typeof(to_variant("CAUSE_OF_DEATH"))),
                                     'PROOF_OF_DEATH_TYPE', array_construct(to_varchar("PROOF_OF_DEATH"), typeof(to_variant("PROOF_OF_DEATH")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 8. BJAZ_CLM_SUPP_EXTN
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_CLM_SUPP_EXTN' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'ADHAAR_PAN_LINK_FLAG', array_construct(to_varchar("ADHAAR_PAN_LINK_FLAG"), typeof(to_variant("ADHAAR_PAN_LINK_FLAG"))),
                                     'MARRIAGE_ANNIVERSARY_DATE', array_construct(to_varchar("MRG_ANNIVERSIRY"), typeof(to_variant("MRG_ANNIVERSIRY"))),
                                     'PAN_ACK_DT', array_construct(to_varchar("PAN_ACK_DT"), typeof(to_variant("PAN_ACK_DT"))),
                                     'PAN_APP_NO', array_construct(to_varchar("PAN_APP_NO"), typeof(to_variant("PAN_APP_NO"))),
                                     'PAN_STATUS', array_construct(to_varchar("PAN_STATUS"), typeof(to_variant("PAN_STATUS"))),
                                     'TWO_YR_ITR_FLAG', array_construct(to_varchar("TWO_YR_ITR_FLAG"), typeof(to_variant("TWO_YR_ITR_FLAG")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 9. BJAZ_HM_MEMBER_DTLS
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_HM_MEMBER_DTLS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'MONTHLY_SALARY', array_construct(to_varchar("MONTHLY_SALARY"), typeof(to_variant("MONTHLY_SALARY")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 10. BJAZ_HM_HOSPITAL_MASTER
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("HOSID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_HM_HOSPITAL_MASTER' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_HOSPITAL_MASTER,
           lateral flatten(input => object_construct_keep_null(
                                     'IMPS_ACTIVE_DATE', array_construct(to_varchar("IMPS_ACTIVE_DATE"), typeof(to_variant("IMPS_ACTIVE_DATE"))),
                                     'IMPS_END_DATE', array_construct(to_varchar("IMPS_END_DATE"), typeof(to_variant("IMPS_END_DATE"))),
                                     'PAYMENT_MODE', array_construct(to_varchar("PAYMENT_MODE"), typeof(to_variant("PAYMENT_MODE")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
),
classified as (
    select v.hkey, v.rs, v.col,
           case
             when equal_null(v.val, r.raw_value) then 0                                                  -- EXACT
             when v.val is null and nullif(trim(r.raw_value), '') is null then 1                         -- BLANK -> NULL (by design)
             when v.val = trim(r.raw_value) then 1                                                       -- WHITESPACE TRIMMED (by design)
             when r.raw_type <> 'VARCHAR' and v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 2             -- TYPED VALUE KEPT, TEXT FORM DIFFERS
             when r.raw_type <> 'VARCHAR' and try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 2
             when v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 3             -- DATE/TIME RE-FORMATTED
             when try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 3             -- NUMBER RE-FORMATTED
             when try_to_decimal(r.raw_value, 38, 12) <> round(try_to_decimal(r.raw_value, 38, 12), 0)
                  and try_to_decimal(v.val, 38, 12) = round(try_to_decimal(r.raw_value, 38, 12), 0) then 4  -- DECIMALS LOST
             when startswith(r.raw_value, v.val) then 5                                                  -- TRUNCATED
             else 6                                                                            -- DIFFERENT VALUE
           end as cls
      from sat_cols v
      join raw_vals r on r.hkey = v.hkey and r.rs_key = v.rs_key and r.col = v.col
),
best as (
    -- a key can have several RAW rows: keep the closest one per (unit, column)
    select hkey, rs, col, min(cls) as cls from classified group by hkey, rs, col
)
select 'OPUS' as project, 'SAT_AUG_PARTY' as satellite, col as sat_column,
       count(*)              as compared,
       count_if(cls = 0)     as exact,
       count_if(cls = 1)     as trimmed_or_blank_to_null,
       count_if(cls = 2)     as typed_value_kept_text_differs,
       count_if(cls = 3)     as reformatted,
       count_if(cls = 4)     as decimals_lost,
       count_if(cls = 5)     as truncated,
       count_if(cls = 6)     as different_value,
       case when count_if(cls in (3, 4, 5)) > 0 then 'FAIL'
            when count_if(cls = 6) > 0 then 'REVIEW (value differs - see DM-A2)'
            when count_if(cls = 1) > 0 then 'PASS (whitespace / blank->null by design)'
            else 'PASS' end  as format_status
  from best
 group by col
 order by col;



----------------------------------------------------------------------------------------
-- 157. OPUS — SAT_AUG_POLICY   [Implemented]
-- 9 mapped column(s), 12 RAW column lineage row(s); 9 column(s) are 1:1 and
-- value-checked in (b). Static transform flags -- integer cast on load (decimals lost if
-- the RAW column has a scale): MEMBER_SEQUENCE<-MEMBER_NO, CUMM_BONUS<-CUMM_BONUS,
-- CUMMULATIVE_AMT<-CUMMULATIVE_AMT, CUMM_BONUS_AMT_COMP<-CUMM_BONUS_AMT_COMP,
-- CUMM_BONUS_AMT_WIDER<-CUMM_BONUS_AMT_WIDER. converted to TIMESTAMP_NTZ on load:
-- INCEPTION_DATE<-INCEPTION_DATE. 5 RAW branch(es): BJAZ_HLT_ENSURE_MEM_DTLS,
-- BJAZ_HM_MEMBER_DTLS, BJAZ_PA_DETL_EXTN, BJAZ_EC_MEM_DTLS_EXTN, BJAZ_SH_MEM_DTLS_EXTN.
----------------------------------------------------------------------------------------
-- SQL query (a) -- column type / length / precision / scale: RAW vs satellite
with lineage (sat_column, raw_db, raw_schema, raw_table, raw_column, transform_flags, transform) as (
    -- generated from the dbt models: every RAW column that feeds a satellite column
    select * from values
        ('MEMBER_SEQUENCE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HLT_ENSURE_MEM_DTLS', 'MEMBER_NO', 'SCALE0, SAT_VARCHAR', '("MEMBER_NO"::number)'),
        ('PREVIOUS_CUM_AMOUNT', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HLT_ENSURE_MEM_DTLS', 'PREVIOUS_CUM_AMOUNT', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("PREVIOUS_CUM_AMOUNT"::varchar), '''')'),
        ('CUMM_BONUS', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_HM_MEMBER_DTLS', 'CUMM_BONUS', 'SCALE0, SAT_VARCHAR', '("CUMM_BONUS"::number)'),
        ('CUMMULATIVE_AMT', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_PA_DETL_EXTN', 'CUMMULATIVE_AMT', 'SCALE0, SAT_VARCHAR', '("CUMMULATIVE_AMT"::number)'),
        ('CUMM_BONUS_AMT_COMP', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_PA_DETL_EXTN', 'CUMM_BONUS_AMT_COMP', 'SCALE0, SAT_VARCHAR', '("CUMM_BONUS_AMT_COMP"::number)'),
        ('CUMM_BONUS_AMT_WIDER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_PA_DETL_EXTN', 'CUMM_BONUS_AMT_WIDER', 'SCALE0, SAT_VARCHAR', '("CUMM_BONUS_AMT_WIDER"::number)'),
        ('CUMM_BONUS_COMP', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_PA_DETL_EXTN', 'CUMM_BONUS_COMP', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("CUMM_BONUS_COMP"::varchar), '''')'),
        ('CUMM_BONUS_WIDER', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_PA_DETL_EXTN', 'CUMM_BONUS_WIDER', 'TRIM, BLANK->NULL, SAT_VARCHAR', 'nullif(trim("CUMM_BONUS_WIDER"::varchar), '''')'),
        ('MEMBER_SEQUENCE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_EC_MEM_DTLS_EXTN', 'MEMBER_NO', 'SCALE0, SAT_VARCHAR', '("MEMBER_NO"::number)'),
        ('INCEPTION_DATE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_EC_MEM_DTLS_EXTN', 'INCEPTION_DATE', 'TO_TIMESTAMP, SAT_VARCHAR', '("INCEPTION_DATE"::timestamp_ntz)'),
        ('MEMBER_SEQUENCE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SH_MEM_DTLS_EXTN', 'MEMBER_NO', 'SCALE0, SAT_VARCHAR', '("MEMBER_NO"::number)'),
        ('INCEPTION_DATE', 'BAGIC_PREPROD_CURATED_DB', 'UTILS', 'BJAZ_SH_MEM_DTLS_EXTN', 'INCEPTION_DATE', 'TO_TIMESTAMP, SAT_VARCHAR', '("INCEPTION_DATE"::timestamp_ntz)')
),
raw_cols as (
    select table_catalog, table_schema, table_name, column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'UTILS'
       and table_name in ('BJAZ_EC_MEM_DTLS_EXTN', 'BJAZ_HLT_ENSURE_MEM_DTLS', 'BJAZ_HM_MEMBER_DTLS', 'BJAZ_PA_DETL_EXTN', 'BJAZ_SH_MEM_DTLS_EXTN')
),
sat_cols as (
    select column_name, data_type, character_maximum_length as char_len, numeric_precision as num_prec,
           numeric_scale as num_scale, datetime_precision as dt_prec
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
     where table_schema = 'BGIL_DATA_MODEL'
       and table_name = 'SAT_AUG_POLICY'
)
select 'OPUS' as project, 'SAT_AUG_POLICY' as satellite,
       l.sat_column, case when s.data_type = 'TEXT' then 'TEXT(' || s.char_len || ')' when s.data_type = 'NUMBER' then 'NUMBER(' || s.num_prec || ',' || s.num_scale || ')' when s.data_type like 'TIMESTAMP%' then s.data_type || '(' || s.dt_prec || ')' else s.data_type end as sat_type,
       l.raw_table, l.raw_column, case when r.data_type = 'TEXT' then 'TEXT(' || r.char_len || ')' when r.data_type = 'NUMBER' then 'NUMBER(' || r.num_prec || ',' || r.num_scale || ')' when r.data_type like 'TIMESTAMP%' then r.data_type || '(' || r.dt_prec || ')' else r.data_type end as raw_type,
       l.transform_flags,
       case
         when r.data_type is null then 'FAIL - RAW COLUMN NOT FOUND'
         when s.data_type is null then 'FAIL - SAT COLUMN NOT FOUND'
         when r.data_type = 'NUMBER' and r.num_scale > 0 and l.transform_flags like '%SCALE0%'
              then 'FAIL - DECIMALS LOST (cast to integer NUMBER on load)'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER' and s.num_scale < r.num_scale then 'FAIL - DECIMALS LOST'
         when r.data_type = 'NUMBER' and s.data_type = 'NUMBER'
              and s.num_prec - s.num_scale < r.num_prec - r.num_scale then 'FAIL - PRECISION RISK'
         when r.data_type = 'TEXT' and s.data_type = 'TEXT' and s.char_len < r.char_len then 'FAIL - TRUNCATION RISK (length)'
         when r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%' and s.dt_prec < r.dt_prec
              then 'FAIL - FRACTIONAL SECONDS TRUNCATED'
         when r.data_type = 'DATE' and s.data_type like 'TIMESTAMP%' then 'REVIEW - DATE LOADED AS TIMESTAMP'
         when r.data_type <> 'TEXT' and s.data_type = 'TEXT' then 'REVIEW - STORED AS TEXT (see query b)'
         when r.data_type = 'TEXT' and s.data_type <> 'TEXT' then 'REVIEW - TEXT CONVERTED TO ' || s.data_type
         when r.data_type <> s.data_type and not (r.data_type like 'TIMESTAMP%' and s.data_type like 'TIMESTAMP%')
              then 'REVIEW - TYPE CHANGED'
         when l.transform_flags like '%TRIM%' then 'PASS (whitespace trimmed by design)'
         else 'PASS'
       end as type_verdict,
       l.transform
  from lineage l
  left join raw_cols r
         on r.table_catalog = l.raw_db and r.table_schema = l.raw_schema
        and r.table_name = l.raw_table and r.column_name = l.raw_column
  left join sat_cols s on s.column_name = l.sat_column
 order by l.sat_column, l.raw_table, l.raw_column;

-- SQL query (b) -- value format on the sample (1:1 mapped columns; run the ALTER SESSION first)
alter session set TIMESTAMP_NTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9',
                  TIMESTAMP_LTZ_OUTPUT_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  TIMESTAMP_TZ_OUTPUT_FORMAT  = 'YYYY-MM-DD HH24:MI:SS.FF9 TZHTZM',
                  DATE_OUTPUT_FORMAT          = 'YYYY-MM-DD';

with sat_rows as (
    -- this project's rows of the satellite
    select s.POLICY_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'MEMBER_SEQUENCE', to_varchar(s."MEMBER_SEQUENCE"),
               'PREVIOUS_CUM_AMOUNT', to_varchar(s."PREVIOUS_CUM_AMOUNT"),
               'CUMM_BONUS', to_varchar(s."CUMM_BONUS"),
               'CUMMULATIVE_AMT', to_varchar(s."CUMMULATIVE_AMT"),
               'CUMM_BONUS_AMT_COMP', to_varchar(s."CUMM_BONUS_AMT_COMP"),
               'CUMM_BONUS_AMT_WIDER', to_varchar(s."CUMM_BONUS_AMT_WIDER"),
               'CUMM_BONUS_COMP', to_varchar(s."CUMM_BONUS_COMP"),
               'CUMM_BONUS_WIDER', to_varchar(s."CUMM_BONUS_WIDER"),
               'INCEPTION_DATE', to_varchar(s."INCEPTION_DATE")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_POLICY s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
raw_vals as (
    -- 1. BJAZ_HLT_ENSURE_MEM_DTLS
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_HLT_ENSURE_MEM_DTLS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HLT_ENSURE_MEM_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'MEMBER_SEQUENCE', array_construct(to_varchar("MEMBER_NO"), typeof(to_variant("MEMBER_NO"))),
                                     'PREVIOUS_CUM_AMOUNT', array_construct(to_varchar("PREVIOUS_CUM_AMOUNT"), typeof(to_variant("PREVIOUS_CUM_AMOUNT")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_HM_MEMBER_DTLS
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_HM_MEMBER_DTLS' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS,
           lateral flatten(input => object_construct_keep_null(
                                     'CUMM_BONUS', array_construct(to_varchar("CUMM_BONUS"), typeof(to_variant("CUMM_BONUS")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BJAZ_PA_DETL_EXTN
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_PA_DETL_EXTN' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PA_DETL_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'CUMMULATIVE_AMT', array_construct(to_varchar("CUMMULATIVE_AMT"), typeof(to_variant("CUMMULATIVE_AMT"))),
                                     'CUMM_BONUS_AMT_COMP', array_construct(to_varchar("CUMM_BONUS_AMT_COMP"), typeof(to_variant("CUMM_BONUS_AMT_COMP"))),
                                     'CUMM_BONUS_AMT_WIDER', array_construct(to_varchar("CUMM_BONUS_AMT_WIDER"), typeof(to_variant("CUMM_BONUS_AMT_WIDER"))),
                                     'CUMM_BONUS_COMP', array_construct(to_varchar("CUMM_BONUS_COMP"), typeof(to_variant("CUMM_BONUS_COMP"))),
                                     'CUMM_BONUS_WIDER', array_construct(to_varchar("CUMM_BONUS_WIDER"), typeof(to_variant("CUMM_BONUS_WIDER")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 4. BJAZ_EC_MEM_DTLS_EXTN
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_EC_MEM_DTLS_EXTN' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'MEMBER_SEQUENCE', array_construct(to_varchar("MEMBER_NO"), typeof(to_variant("MEMBER_NO"))),
                                     'INCEPTION_DATE', array_construct(to_varchar("INCEPTION_DATE"), typeof(to_variant("INCEPTION_DATE")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 5. BJAZ_SH_MEM_DTLS_EXTN
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_SH_MEM_DTLS_EXTN' as rs_key,
           f.key as col, as_varchar(f.value[0]) as raw_value, as_varchar(f.value[1]) as raw_type
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN,
           lateral flatten(input => object_construct_keep_null(
                                     'MEMBER_SEQUENCE', array_construct(to_varchar("MEMBER_NO"), typeof(to_variant("MEMBER_NO"))),
                                     'INCEPTION_DATE', array_construct(to_varchar("INCEPTION_DATE"), typeof(to_variant("INCEPTION_DATE")))
                                 )) f
    ) where hkey in (select hkey from sample_keys)
),
classified as (
    select v.hkey, v.rs, v.col,
           case
             when equal_null(v.val, r.raw_value) then 0                                                  -- EXACT
             when v.val is null and nullif(trim(r.raw_value), '') is null then 1                         -- BLANK -> NULL (by design)
             when v.val = trim(r.raw_value) then 1                                                       -- WHITESPACE TRIMMED (by design)
             when r.raw_type <> 'VARCHAR' and v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 2             -- TYPED VALUE KEPT, TEXT FORM DIFFERS
             when r.raw_type <> 'VARCHAR' and try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 2
             when v.val like '____-__-__%' and r.raw_value like '____-__-__%'
                  and try_to_timestamp_ntz(v.val) = try_to_timestamp_ntz(r.raw_value) then 3             -- DATE/TIME RE-FORMATTED
             when try_to_decimal(v.val, 38, 12) = try_to_decimal(r.raw_value, 38, 12) then 3             -- NUMBER RE-FORMATTED
             when try_to_decimal(r.raw_value, 38, 12) <> round(try_to_decimal(r.raw_value, 38, 12), 0)
                  and try_to_decimal(v.val, 38, 12) = round(try_to_decimal(r.raw_value, 38, 12), 0) then 4  -- DECIMALS LOST
             when startswith(r.raw_value, v.val) then 5                                                  -- TRUNCATED
             else 6                                                                            -- DIFFERENT VALUE
           end as cls
      from sat_cols v
      join raw_vals r on r.hkey = v.hkey and r.rs_key = v.rs_key and r.col = v.col
),
best as (
    -- a key can have several RAW rows: keep the closest one per (unit, column)
    select hkey, rs, col, min(cls) as cls from classified group by hkey, rs, col
)
select 'OPUS' as project, 'SAT_AUG_POLICY' as satellite, col as sat_column,
       count(*)              as compared,
       count_if(cls = 0)     as exact,
       count_if(cls = 1)     as trimmed_or_blank_to_null,
       count_if(cls = 2)     as typed_value_kept_text_differs,
       count_if(cls = 3)     as reformatted,
       count_if(cls = 4)     as decimals_lost,
       count_if(cls = 5)     as truncated,
       count_if(cls = 6)     as different_value,
       case when count_if(cls in (3, 4, 5)) > 0 then 'FAIL'
            when count_if(cls = 6) > 0 then 'REVIEW (value differs - see DM-A2)'
            when count_if(cls = 1) > 0 then 'PASS (whitespace / blank->null by design)'
            else 'PASS' end  as format_status
  from best
 group by col
 order by col;
